/// Map an ISel operand to the arch-neutral guard operand ref the kernel uses (regs + imms only),
/// for fingerprinting a guard carrier's operand identity at selection time.
fn isel_operand_guard_ref(op: &ISelOperand) -> Option<GuardOperandRef> {
    match op {
        ISelOperand::VReg(v) => Some(GuardOperandRef::Reg(v.id)),
        ISelOperand::Imm(i) => Some(GuardOperandRef::Imm(*i)),
        _ => None,
    }
}

/// Derive the overflow carrier's [`GuardKind`] from its op-tag, EXACTLY as the kernel-side
/// `overflow_carrier_kind` does from the emitted carrier's third operand. Signed add/sub map to
/// [`GuardKind::SignedOverflow`]; unsigned add/sub map to [`GuardKind::UnsignedOverflow`]; a
/// malformed tag yields `None` (the kernel would likewise refuse to classify it). Keeping the two
/// derivations identical is what makes the carrier→obligation binding key symmetric across the
/// record and re-derive sides.
fn overflow_kind_from_op_tag(op_tag: i64) -> Option<GuardKind> {
    use trust_cg_ir::overflow_tag::{OverflowOp, unpack_overflow_tag};
    let (op, _width) = unpack_overflow_tag(op_tag)?;
    match op {
        OverflowOp::SignedAdd | OverflowOp::SignedSub | OverflowOp::SignedMul => {
            Some(GuardKind::SignedOverflow)
        }
        OverflowOp::UnsignedAdd | OverflowOp::UnsignedSub | OverflowOp::UnsignedMul => {
            Some(GuardKind::UnsignedOverflow)
        }
    }
}

// ---------------------------------------------------------------------------
// Register model helpers
// ---------------------------------------------------------------------------

/// Derive the register class for a given LIR type.
fn reg_class_for_type(ty: &Type) -> RegClass {
    match ty {
        // Keep boolean values in 64-bit GPR virtual registers. Integer
        // comparisons already materialize B1 values with CSET into Gpr64 to
        // avoid Wn/Xn alias hazards during register allocation; block params,
        // constants, copies, and ABI moves need the same class.
        Type::B1 => RegClass::Gpr64,
        Type::I8 | Type::I16 | Type::I32 => RegClass::Gpr32,
        Type::I64 | Type::I128 => RegClass::Gpr64,
        Type::F16 => RegClass::Fpr16,
        Type::F32 => RegClass::Fpr32,
        Type::F64 => RegClass::Fpr64,
        Type::V128 => RegClass::Fpr128,
        // 64-bit NEON vectors live in the Fpr64 (D-register) class.
        Type::V64 => RegClass::Fpr64,
        // Aggregates are handled via pointers at the machine level.
        Type::Struct(_) | Type::Array(_, _) | Type::Enum { .. } => RegClass::Gpr64,
    }
}

/// 16-bit system register encoding for TPIDR_EL0.
const TPIDR_EL0_SYSREG: i64 = 0xDE82;

/// Maximum constant length (in bytes) for which `select_memcpy` inlines the
/// copy as an exact-width load/store sequence instead of a libc `memcpy` call.
/// Above this the call overhead is amortized and the inline expansion (which
/// grows one load/store pair per residual lane) stops paying for itself.
const INLINE_MEMCPY_MAX_BYTES: i64 = 32;

/// Decompose a non-negative constant byte offset into the single AArch64
/// `ADD (immediate)` form that materializes it, if one exists.
///
/// `ADD Xd, Xn, #imm{, LSL #12}` encodes a 12-bit unsigned immediate with an
/// optional left shift of 12. This returns:
///   * `AddRI` with `off` itself for `off <= 0xFFF`;
///   * `AddRIShift12` with the PRE-shift value `off >> 12` for an `off` whose
///     low 12 bits are clear and whose high half fits 12 bits (mirrors the TLS
///     local-exec add and the encoder's `imm12_operand`, which re-applies the
///     `<< 12`);
///   * `None` for a negative offset, or one needing two adds (both halves set),
///     or one beyond `0xFFF << 12` — the caller then falls back to
///     materialize-and-add. A `0xFADE` global-address stub (decoded to a
///     `GlobalRef`/`ExternRef` before ISel, never a plain `Iconst` here) would
///     be rejected by this ceiling even if one reached the fold site.
fn aarch64_add_imm12_form(off: i64) -> Option<(AArch64Opcode, i64)> {
    if off < 0 {
        return None;
    }
    if off <= 0xFFF {
        return Some((AArch64Opcode::AddRI, off));
    }
    if off & 0xFFF == 0 && (off >> 12) <= 0xFFF {
        return Some((AArch64Opcode::AddRIShift12, off >> 12));
    }
    None
}

// ---------------------------------------------------------------------------
// Error type
// ---------------------------------------------------------------------------

/// Errors during instruction selection.
#[derive(Debug, Error)]
pub enum ISelError {
    #[error("value {0:?} not defined before use")]
    UndefinedValue(Value),
    #[error(
        "LIR block id {block} is in the selector-synthesized id range (>= 2^31); refusing to select it (fail-closed id-space guard)"
    )]
    BlockIdInSyntheticRange { block: u32 },
    #[error(
        "block {block} already contains instructions at first selection — a synthesized block (switch BST node / trap block) aliased a real LIR block id; refusing to merge control flow (fail-closed, A64-4/JIT-2 class)"
    )]
    BlockAlreadyPopulated { block: u32 },
    #[error("unsupported type for Fconst: {0:?} (expected F32 or F64)")]
    UnsupportedFconstType(Type),
    #[error("unsupported opcode for AArch64 ISel: {0}")]
    UnsupportedOpcode(String),
    #[error("unsupported integer type for {op}: {ty:?}")]
    UnsupportedIntegerType { op: &'static str, ty: Type },
    #[error(
        "unsupported AArch64 CmpXchg for {ty:?} with success {success:?} and failure {failure:?}: {reason}"
    )]
    UnsupportedCmpXchg {
        ty: Type,
        success: AtomicOrdering,
        failure: AtomicOrdering,
        reason: &'static str,
    },
    #[error("unsupported AArch64 AtomicRmw {op:?} for {ty:?} with {ordering:?}: {reason}")]
    UnsupportedAtomicRmw {
        op: AtomicRmwOp,
        ty: Type,
        ordering: AtomicOrdering,
        reason: &'static str,
    },
    #[error("unsupported ABI location for return value: stack-passed returns are not supported")]
    UnsupportedReturnLocation,
    #[error(
        "Return arity mismatch: function signature declares {expected} return value(s) but Return instruction has {actual} arg(s); every non-void function must pass its return value(s) in Return.args"
    )]
    ReturnArityMismatch { expected: usize, actual: usize },
    #[error(
        "Return type mismatch at index {index}: signature declares {expected} but Return arg has type {actual}"
    )]
    ReturnTypeMismatch {
        index: usize,
        expected: String,
        actual: String,
    },
    #[error("unsupported ABI location for argument: RegSequence on non-aggregate type")]
    UnsupportedArgLocation,
    #[error(
        "malformed instruction: expected at least {expected} args, got {actual} (opcode context: {context})"
    )]
    InsufficientArgs {
        expected: usize,
        actual: usize,
        context: &'static str,
    },
    #[error(
        "malformed instruction: expected exactly {expected} args, got {actual} (opcode context: {context})"
    )]
    WrongArgCount {
        expected: usize,
        actual: usize,
        context: &'static str,
    },
    #[error("malformed instruction: expected no results, got {actual} (opcode context: {context})")]
    UnexpectedResults {
        actual: usize,
        context: &'static str,
    },
    #[error("malformed instruction: expected at least 1 result (opcode context: {0})")]
    MissingResult(&'static str),
    #[error("StructGep on non-struct type: {0:?}")]
    StructGepNonStruct(Type),
    #[error("StructGep field index {index} out of range for struct with {field_count} fields")]
    StructGepOutOfRange { index: u32, field_count: usize },
    #[error("ArrayGep with zero-sized element type: {0:?}")]
    ArrayGepZeroSized(Type),
    #[error("aggregate type too large for inline return: {0} bytes")]
    AggregateReturnTooLarge(u32),
    #[error("LocalExec TlsRef requires local_exec_offset")]
    LocalExecTlsRefMissingOffset,
    #[error("LocalExec TlsRef offset too large for imm12 hi/lo pair")]
    LocalExecTlsRefOffsetTooLarge,
    #[error("unsupported AArch64 TlsRef model {model:?}: {reason}")]
    UnsupportedTlsRefModel {
        model: TlsModel,
        reason: &'static str,
    },
    #[error("runtime-sized StackAddr slot {slot} has unknown size source")]
    RuntimeStackSlotUnknownSizeSource { slot: u32 },
    #[error("internal error: block not found in ISel function")]
    BlockNotFound,
    #[error("switch normalization does not preserve source case mapping ({strategy}): {reason}")]
    SwitchNormalizationMismatch {
        strategy: &'static str,
        reason: String,
    },
    #[error("invalid AArch64 exception-handling metadata: {0}")]
    InvalidEhMetadata(String),
}

