    #[test]
    fn select_zero_minus_mul_one_use_emits_mneg_shape() {
        let sig = Signature {
            params: vec![Type::I64, Type::I64],
            returns: vec![Type::I64],
        };
        let mut isel = InstructionSelector::new("mul_neg64".to_string(), sig.clone());
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();
        let instructions = vec![
            Instruction {
                opcode: Opcode::Iconst {
                    ty: Type::I64,
                    imm: 0,
                },
                args: vec![],
                results: vec![Value(2)],
            },
            Instruction {
                opcode: Opcode::Imul,
                args: vec![Value(0), Value(1)],
                results: vec![Value(3)],
            },
            Instruction {
                opcode: Opcode::Isub,
                args: vec![Value(2), Value(3)],
                results: vec![Value(4)],
            },
            Instruction {
                opcode: Opcode::Return,
                args: vec![Value(4)],
                results: vec![],
            },
        ];

        isel.select_block(entry, &instructions).unwrap();
        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];

        let msub = mblock
            .insts
            .iter()
            .find(|inst| inst.opcode == AArch64Opcode::Msub)
            .expect("Isub(0, Imul) should select to MNEG-shaped MSUB");
        assert_eq!(
            msub.operands.len(),
            3,
            "three-operand MSUB encodes the MNEG alias with Ra=XZR"
        );
        assert!(
            !mblock
                .insts
                .iter()
                .any(|inst| inst.opcode == AArch64Opcode::MulRR),
            "MNEG-shaped fuse must skip the standalone MUL"
        );
        assert!(
            !mblock
                .insts
                .iter()
                .any(|inst| inst.opcode == AArch64Opcode::SubRR),
            "MNEG-shaped fuse must skip the standalone SUB"
        );
        assert!(
            !mblock
                .insts
                .iter()
                .any(|inst| inst.opcode == AArch64Opcode::Movz),
            "single-use zero addend should be folded into Ra=XZR"
        );
    }

    #[test]
    fn select_mul_sub_does_not_fuse_product_minus_addend() {
        let (mut isel, entry) = make_i64_3arg_isel();
        let instructions = vec![
            Instruction {
                opcode: Opcode::Imul,
                args: vec![Value(0), Value(1)],
                results: vec![Value(3)],
            },
            Instruction {
                opcode: Opcode::Isub,
                args: vec![Value(3), Value(2)],
                results: vec![Value(4)],
            },
            Instruction {
                opcode: Opcode::Return,
                args: vec![Value(4)],
                results: vec![],
            },
        ];

        isel.select_block(entry, &instructions).unwrap();
        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];

        assert!(
            mblock
                .insts
                .iter()
                .any(|inst| inst.opcode == AArch64Opcode::MulRR),
            "product - addend is not representable as MSUB without changing semantics"
        );
        assert!(
            mblock
                .insts
                .iter()
                .any(|inst| inst.opcode == AArch64Opcode::SubRR),
            "product - addend should remain a standalone SUB"
        );
        assert!(
            !mblock
                .insts
                .iter()
                .any(|inst| inst.opcode == AArch64Opcode::Msub),
            "product - addend must not select MSUB"
        );
    }

    #[test]
    fn select_mul_add_does_not_fuse_i32_product_into_i64_address_add() {
        let sig = Signature {
            params: vec![Type::I32, Type::I32, Type::I64],
            returns: vec![Type::I64],
        };
        let mut isel = InstructionSelector::new("mixed_addr_add".to_string(), sig.clone());
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();

        let instructions = vec![
            Instruction {
                opcode: Opcode::Imul,
                args: vec![Value(0), Value(1)],
                results: vec![Value(3)],
            },
            Instruction {
                opcode: Opcode::Iadd,
                args: vec![Value(2), Value(3)],
                results: vec![Value(4)],
            },
            Instruction {
                opcode: Opcode::Return,
                args: vec![Value(4)],
                results: vec![],
            },
        ];

        isel.select_block(entry, &instructions).unwrap();
        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];

        assert!(
            !mblock
                .insts
                .iter()
                .any(|inst| inst.opcode == AArch64Opcode::Madd),
            "i32 product plus i64 addend must not select a 32-bit MADD"
        );

        let add = mblock
            .insts
            .iter()
            .find(|inst| inst.opcode == AArch64Opcode::AddRR)
            .expect("mixed address add should lower to AddRR after widening");
        match add.operands[0] {
            ISelOperand::VReg(vreg) => assert_eq!(vreg.class, RegClass::Gpr64),
            ref other => panic!("expected Gpr64 vreg destination, got {other:?}"),
        }
        assert!(
            mblock
                .insts
                .iter()
                .any(|inst| inst.opcode == AArch64Opcode::Uxtw),
            "i32 product must be widened before the i64 address add"
        );
    }

