    #[test]
    fn select_mul_add_keeps_mul_when_product_has_multiple_uses() {
        let (mut isel, entry) = make_i64_3arg_isel();
        let instructions = vec![
            Instruction {
                opcode: Opcode::Imul,
                args: vec![Value(0), Value(1)],
                results: vec![Value(3)],
            },
            Instruction {
                opcode: Opcode::Iadd,
                args: vec![Value(3), Value(2)],
                results: vec![Value(4)],
            },
            Instruction {
                opcode: Opcode::Isub,
                args: vec![Value(3), Value(2)],
                results: vec![Value(5)],
            },
            Instruction {
                opcode: Opcode::Return,
                args: vec![Value(4)],
                results: vec![],
            },
        ];

        isel.select_block(entry, &instructions).unwrap();
        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];

        assert!(
            mblock
                .insts
                .iter()
                .any(|inst| inst.opcode == AArch64Opcode::MulRR),
            "multi-use product must keep the standalone MUL"
        );
        assert!(
            mblock
                .insts
                .iter()
                .any(|inst| inst.opcode == AArch64Opcode::AddRR),
            "multi-use product must keep the standalone ADD"
        );
        assert!(
            !mblock
                .insts
                .iter()
                .any(|inst| inst.opcode == AArch64Opcode::Madd),
            "multi-use product must not be fused"
        );
    }

    /// Helper: create isel for fn(f64, f64) -> f64.
    fn make_f64_isel() -> (InstructionSelector, Block) {
        let sig = Signature {
            params: vec![Type::F64, Type::F64],
            returns: vec![Type::F64],
        };
        let mut isel = InstructionSelector::new("fpop".to_string(), sig.clone());
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();
        (isel, entry)
    }

    /// Helper: create isel for fn(f32, f32) -> f32.
    fn make_f32_isel() -> (InstructionSelector, Block) {
        let sig = Signature {
            params: vec![Type::F32, Type::F32],
            returns: vec![Type::F32],
        };
        let mut isel = InstructionSelector::new("fpop32".to_string(), sig.clone());
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();
        (isel, entry)
    }

    /// Helper: create isel with no args, manually defining values.
    fn make_empty_isel() -> (InstructionSelector, Block) {
        let sig = Signature {
            params: vec![],
            returns: vec![],
        };
        let mut isel = InstructionSelector::new("test".to_string(), sig);
        let entry = Block(0);
        isel.func.ensure_block(entry);
        (isel, entry)
    }

