    #[test]
    fn lower_formal_arguments_two_i32() {
        let (isel, entry) = make_add_isel();
        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];

        assert_eq!(mblock.insts.len(), 2);
        assert_eq!(mblock.insts[0].opcode, AArch64Opcode::Copy);
        assert_eq!(mblock.insts[1].opcode, AArch64Opcode::Copy);
        assert_eq!(mblock.insts[0].operands[1], ISelOperand::PReg(PReg::new(0))); // X0
        assert_eq!(mblock.insts[1].operands[1], ISelOperand::PReg(PReg::new(1)));
        // X1
    }

    #[test]
    fn lower_formal_arguments_small_i64_struct_materializes_register_to_slot() {
        let sig = Signature {
            params: vec![Type::Struct(vec![Type::I64])],
            returns: vec![],
        };
        let mut isel = InstructionSelector::new("small_struct_formal".to_string(), sig.clone());
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();

        match isel.value_map.get(&Value(0)) {
            Some(ISelOperand::VReg(vreg)) => assert_eq!(vreg.class, RegClass::Gpr64),
            other => {
                panic!("expected aggregate formal value to be stack-address vreg, got {other:?}")
            }
        }

        let mfunc = isel.finalize();
        assert_eq!(mfunc.stack_slots.len(), 1);
        assert_eq!(mfunc.stack_slots[0].size, 8);
        assert_eq!(mfunc.stack_slots[0].align, 8);

        let mblock = &mfunc.blocks[&entry];
        assert_eq!(mblock.insts.len(), 2);
        assert_eq!(mblock.insts[0].opcode, AArch64Opcode::AddPCRel);
        assert_eq!(mblock.insts[0].operands[1], ISelOperand::PReg(SP));
        assert_eq!(mblock.insts[0].operands[2], ISelOperand::StackSlot(0));
        assert_eq!(mblock.insts[1].opcode, AArch64Opcode::StrRI);
        assert_eq!(mblock.insts[1].operands[0], ISelOperand::PReg(gpr::X0));
        assert_eq!(mblock.insts[1].operands[2], ISelOperand::Imm(0));
    }

    #[test]
    fn lower_formal_arguments_small_struct_reserves_trailing_scalar_livein() {
        let sig = Signature {
            params: vec![Type::Struct(vec![Type::I64]), Type::I64],
            returns: vec![],
        };
        let mut isel =
            InstructionSelector::new("small_struct_then_scalar_formal".to_string(), sig.clone());
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();

        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];
        assert_eq!(mblock.insts.len(), 3);
        assert_eq!(mblock.insts[0].opcode, AArch64Opcode::AddPCRel);
        assert!(
            mblock.insts[0].implicit_uses.contains(&gpr::X0),
            "aggregate slot-address materialization must reserve the unread aggregate register"
        );
        assert!(
            mblock.insts[0].implicit_uses.contains(&gpr::X1),
            "aggregate slot-address materialization must reserve the trailing scalar register"
        );
        assert_eq!(mblock.insts[1].opcode, AArch64Opcode::StrRI);
        assert_eq!(mblock.insts[1].operands[0], ISelOperand::PReg(gpr::X0));
        assert!(
            mblock.insts[1].implicit_uses.contains(&gpr::X1),
            "aggregate store must reserve the trailing scalar register"
        );
        assert!(
            !mblock.insts[1].implicit_uses.contains(&gpr::X0),
            "the aggregate source register is already an explicit use"
        );
        assert_eq!(mblock.insts[2].opcode, AArch64Opcode::Copy);
        assert_eq!(mblock.insts[2].operands[1], ISelOperand::PReg(gpr::X1));
    }

    #[test]
    fn lower_formal_arguments_medium_struct_materializes_regpair_to_slot() {
        let sig = Signature {
            params: vec![Type::Struct(vec![Type::I64, Type::I32])],
            returns: vec![],
        };
        let mut isel = InstructionSelector::new("medium_struct_formal".to_string(), sig.clone());
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();

        match isel.value_map.get(&Value(0)) {
            Some(ISelOperand::VReg(vreg)) => assert_eq!(vreg.class, RegClass::Gpr64),
            other => {
                panic!("expected aggregate formal value to be stack-address vreg, got {other:?}")
            }
        }

        let mfunc = isel.finalize();
        assert_eq!(mfunc.stack_slots.len(), 1);
        assert_eq!(mfunc.stack_slots[0].size, 16);
        assert_eq!(mfunc.stack_slots[0].align, 8);

        let mblock = &mfunc.blocks[&entry];
        assert_eq!(mblock.insts.len(), 3);
        assert_eq!(mblock.insts[0].opcode, AArch64Opcode::AddPCRel);
        assert_eq!(mblock.insts[0].operands[1], ISelOperand::PReg(SP));
        assert_eq!(mblock.insts[0].operands[2], ISelOperand::StackSlot(0));
        assert_eq!(mblock.insts[1].opcode, AArch64Opcode::StrRI);
        assert_eq!(mblock.insts[1].operands[0], ISelOperand::PReg(gpr::X0));
        assert_eq!(mblock.insts[1].operands[2], ISelOperand::Imm(0));
        assert_eq!(mblock.insts[2].opcode, AArch64Opcode::StrRI);
        assert_eq!(mblock.insts[2].operands[0], ISelOperand::PReg(gpr::X1));
        assert_eq!(mblock.insts[2].operands[2], ISelOperand::Imm(8));
    }

    #[test]
    fn lower_formal_arguments_medium_struct_reserves_trailing_scalar_livein() {
        let sig = Signature {
            params: vec![Type::Struct(vec![Type::I64, Type::I32]), Type::I64],
            returns: vec![],
        };
        let mut isel =
            InstructionSelector::new("medium_struct_then_scalar_formal".to_string(), sig.clone());
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();

        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];
        assert_eq!(mblock.insts.len(), 4);
        assert_eq!(mblock.insts[0].opcode, AArch64Opcode::AddPCRel);
        for preg in [gpr::X0, gpr::X1, gpr::X2] {
            assert!(
                mblock.insts[0].implicit_uses.contains(&preg),
                "aggregate slot-address materialization must reserve unread formal {preg:?}"
            );
        }

        assert_eq!(mblock.insts[1].opcode, AArch64Opcode::StrRI);
        assert_eq!(mblock.insts[1].operands[0], ISelOperand::PReg(gpr::X0));
        assert!(
            mblock.insts[1].implicit_uses.contains(&gpr::X1),
            "low-half store must reserve the unread high-half formal"
        );
        assert!(
            mblock.insts[1].implicit_uses.contains(&gpr::X2),
            "low-half store must reserve the trailing scalar formal"
        );
        assert!(
            !mblock.insts[1].implicit_uses.contains(&gpr::X0),
            "the low-half source register is already an explicit use"
        );

        assert_eq!(mblock.insts[2].opcode, AArch64Opcode::StrRI);
        assert_eq!(mblock.insts[2].operands[0], ISelOperand::PReg(gpr::X1));
        assert!(
            mblock.insts[2].implicit_uses.contains(&gpr::X2),
            "high-half store must reserve the trailing scalar formal"
        );
        assert_eq!(mblock.insts[3].opcode, AArch64Opcode::Copy);
        assert_eq!(mblock.insts[3].operands[1], ISelOperand::PReg(gpr::X2));
    }

