    #[test]
    fn lower_formal_arguments_hfa_f32_materializes_typed_regs_to_slot() {
        let hfa_ty = Type::Array(Box::new(Type::F32), 3);
        let sig = Signature {
            params: vec![hfa_ty],
            returns: vec![],
        };
        let mut isel = InstructionSelector::new("hfa_f32_formal".to_string(), sig.clone());
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();

        match isel.value_map.get(&Value(0)) {
            Some(ISelOperand::VReg(vreg)) => assert_eq!(vreg.class, RegClass::Gpr64),
            other => {
                panic!("expected HFA formal value to be stack-address vreg, got {other:?}")
            }
        }

        let mfunc = isel.finalize();
        assert_eq!(mfunc.stack_slots.len(), 1);
        assert_eq!(mfunc.stack_slots[0].size, 12);
        assert_eq!(mfunc.stack_slots[0].align, 8);

        let mblock = &mfunc.blocks[&entry];
        assert_eq!(mblock.insts.len(), 4);
        assert_eq!(mblock.insts[0].opcode, AArch64Opcode::AddPCRel);
        assert_eq!(mblock.insts[0].operands[1], ISelOperand::PReg(SP));
        assert_eq!(mblock.insts[0].operands[2], ISelOperand::StackSlot(0));

        for (inst_index, (preg, offset)) in [(gpr::S0, 0), (gpr::S1, 4), (gpr::S2, 8)]
            .into_iter()
            .enumerate()
        {
            let inst = &mblock.insts[inst_index + 1];
            assert_eq!(inst.opcode, AArch64Opcode::StrRI);
            assert_eq!(inst.operands[0], ISelOperand::PReg(preg));
            assert_eq!(inst.operands[2], ISelOperand::Imm(offset));
        }
    }

    #[test]
    fn lower_formal_arguments_hfa_f64_reserves_trailing_scalar_livein() {
        let sig = Signature {
            params: vec![Type::Struct(vec![Type::F64, Type::F64]), Type::F64],
            returns: vec![],
        };
        let mut isel =
            InstructionSelector::new("hfa_f64_then_scalar_formal".to_string(), sig.clone());
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();

        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];
        assert_eq!(mblock.insts.len(), 4);
        assert_eq!(mblock.insts[0].opcode, AArch64Opcode::AddPCRel);
        for preg in [gpr::D0, gpr::D1, gpr::D2] {
            assert!(
                mblock.insts[0].implicit_uses.contains(&preg),
                "HFA slot-address materialization must reserve unread formal {preg:?}"
            );
        }

        assert_eq!(mblock.insts[1].opcode, AArch64Opcode::StrRI);
        assert_eq!(mblock.insts[1].operands[0], ISelOperand::PReg(gpr::D0));
        assert!(
            mblock.insts[1].implicit_uses.contains(&gpr::D1),
            "first HFA store must reserve the unread second HFA lane"
        );
        assert!(
            mblock.insts[1].implicit_uses.contains(&gpr::D2),
            "first HFA store must reserve the trailing scalar formal"
        );
        assert_eq!(mblock.insts[2].opcode, AArch64Opcode::StrRI);
        assert_eq!(mblock.insts[2].operands[0], ISelOperand::PReg(gpr::D1));
        assert_eq!(mblock.insts[2].operands[2], ISelOperand::Imm(8));
        assert!(
            mblock.insts[2].implicit_uses.contains(&gpr::D2),
            "second HFA store must reserve the trailing scalar formal"
        );
        assert_eq!(mblock.insts[3].opcode, AArch64Opcode::Copy);
        assert_eq!(mblock.insts[3].operands[1], ISelOperand::PReg(gpr::D2));
    }

    #[test]
    fn lower_formal_arguments_reserves_unread_mixed_width_regs() {
        let sig = Signature {
            params: vec![
                Type::I64,
                Type::I64,
                Type::I64,
                Type::I32,
                Type::I64,
                Type::I64,
            ],
            returns: vec![],
        };
        let mut isel = InstructionSelector::new("mixed_width_formals".to_string(), sig.clone());
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();

        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];

        assert_eq!(mblock.insts.len(), 6);
        assert_eq!(mblock.insts[3].operands[1], ISelOperand::PReg(gpr::X3));
        assert!(
            mblock.insts[3].implicit_uses.contains(&gpr::X4),
            "the I32 formal copy must reserve the unread pointer in X4"
        );
        assert!(
            mblock.insts[3].implicit_uses.contains(&gpr::X5),
            "the I32 formal copy must reserve later unread formals"
        );
        assert!(
            !mblock.insts[3].implicit_uses.contains(&gpr::X3),
            "the source register is already an explicit use"
        );
    }

    #[test]
    fn lower_formal_arguments_i128_regpair_reserves_later_formals() {
        let sig = Signature {
            params: vec![Type::I128, Type::I64],
            returns: vec![],
        };
        let mut isel = InstructionSelector::new("i128_then_i64_formals".to_string(), sig.clone());
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();

        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];

        assert_eq!(mblock.insts.len(), 3);
        assert_eq!(mblock.insts[0].operands[1], ISelOperand::PReg(gpr::X0));
        assert!(
            mblock.insts[0].implicit_uses.contains(&gpr::X1),
            "the low-half copy must reserve the unread high half"
        );
        assert!(
            mblock.insts[0].implicit_uses.contains(&gpr::X2),
            "the low-half copy must reserve the later scalar formal"
        );

        assert_eq!(mblock.insts[1].operands[1], ISelOperand::PReg(gpr::X1));
        assert!(
            mblock.insts[1].implicit_uses.contains(&gpr::X2),
            "the high-half copy must reserve the later scalar formal"
        );
        assert!(
            mblock.insts[1].implicit_uses.contains(&gpr::X0),
            "the high-half copy must reserve the earlier low half if scheduled first"
        );
        assert!(
            !mblock.insts[1].implicit_uses.contains(&gpr::X1),
            "the source register is already an explicit use"
        );

        assert_eq!(mblock.insts[2].operands[1], ISelOperand::PReg(gpr::X2));
    }

