    #[test]
    fn cmp_imm12_fold_accepts_in_range_and_rejects_out_of_range() {
        use InstructionSelector as S;
        // Zero and one always fold at every width (and `#0` is what enables
        // CBZ/CBNZ fusion downstream).
        for ty in [Type::I8, Type::I16, Type::I32, Type::I64] {
            assert_eq!(S::cmp_imm12_fold(&ty, false, 0), Some(0));
            assert_eq!(S::cmp_imm12_fold(&ty, true, 0), Some(0));
            assert_eq!(S::cmp_imm12_fold(&ty, false, 1), Some(1));
        }
        // imm12 boundary: 4095 folds, 4096 does not (no shifted-imm12 form).
        assert_eq!(S::cmp_imm12_fold(&Type::I32, false, 4095), Some(4095));
        assert_eq!(S::cmp_imm12_fold(&Type::I32, false, 4096), None);
        assert_eq!(S::cmp_imm12_fold(&Type::I64, false, 4095), Some(4095));
        assert_eq!(S::cmp_imm12_fold(&Type::I64, false, 4096), None);
        // Negative constants never fold (no CMN form); they drop to CmpRR.
        assert_eq!(S::cmp_imm12_fold(&Type::I32, true, -1), None);
        assert_eq!(S::cmp_imm12_fold(&Type::I64, true, -1), None);
        assert_eq!(S::cmp_imm12_fold(&Type::I32, true, -4096), None);
    }

    #[test]
    fn cmp_imm12_fold_narrow_widths_match_the_extend_discipline() {
        use InstructionSelector as S;
        // Unsigned narrow: the byte/half is zero-extended, so it folds whenever
        // it lands in [0, 4095].
        assert_eq!(S::cmp_imm12_fold(&Type::I8, false, 255), Some(255));
        assert_eq!(S::cmp_imm12_fold(&Type::I8, false, 0x1FF), Some(0xFF)); // low byte only
        assert_eq!(S::cmp_imm12_fold(&Type::I16, false, 4095), Some(4095));
        assert_eq!(S::cmp_imm12_fold(&Type::I16, false, 4096), None);
        assert_eq!(S::cmp_imm12_fold(&Type::I16, false, 65535), None);
        // Signed narrow: positive-in-range values fold; a byte/half whose SIGNED
        // value is negative sign-extends to a > 4095 unsigned 32-bit value and
        // must NOT fold (matches SXTB/SXTH of the constant, then CmpRR).
        assert_eq!(S::cmp_imm12_fold(&Type::I8, true, 127), Some(127));
        assert_eq!(S::cmp_imm12_fold(&Type::I8, true, 128), None); // (i8)128 = -128
        assert_eq!(S::cmp_imm12_fold(&Type::I8, true, 200), None); // (i8)200 = -56
        assert_eq!(S::cmp_imm12_fold(&Type::I16, true, 4095), Some(4095));
        assert_eq!(S::cmp_imm12_fold(&Type::I16, true, 32768), None); // (i16)32768 = -32768
    }

    #[test]
    fn select_cmp_folds_constant_rhs_to_cmpri() {
        // `icmp ne i32 x, 0` with a constant 0 RHS must lower to `CmpRI x, #0`
        // (not a materialized-constant `CmpRR`), which the cmp-branch-fusion
        // pass later folds to CBZ/CBNZ.
        let sig = Signature {
            params: vec![Type::I32],
            returns: vec![Type::B1],
        };
        let mut isel = InstructionSelector::new("cmp_fold".to_string(), sig);
        let entry = Block(0);
        isel.value_types.insert(Value(0), Type::I32);
        isel.value_types.insert(Value(2), Type::B1);
        // Value(1) is an i32 constant 0.
        isel.iconst_origins.insert(Value(1), (Type::I32, 0));
        let x = isel.new_vreg(RegClass::Gpr32);
        isel.value_map.insert(Value(0), ISelOperand::VReg(x));
        isel.current_block = Some(entry);
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Icmp {
                    cond: IntCC::NotEqual,
                },
                args: vec![Value(0), Value(1)],
                results: vec![Value(2)],
            },
            entry,
        )
        .unwrap();
        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];
        let cmp = mblock
            .insts
            .iter()
            .find(|i| matches!(i.opcode, AArch64Opcode::CmpRI | AArch64Opcode::CmpRR))
            .expect("a compare must be emitted");
        assert_eq!(
            cmp.opcode,
            AArch64Opcode::CmpRI,
            "constant-0 RHS must fold to CmpRI, enabling CBZ/CBNZ"
        );
        assert_eq!(cmp.operands[1], ISelOperand::Imm(0));
    }

