    #[test]
    fn select_lsl_i32_immediate() {
        // Test immediate shift: define a constant shift amount, then shift
        let (mut isel, entry) = make_empty_isel();

        // Value(0) = iconst i32, 100
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Iconst {
                    ty: Type::I32,
                    imm: 100,
                },
                args: vec![],
                results: vec![Value(0)],
            },
            entry,
        )
        .unwrap();

        // Value(1) = iconst i32, 4 (shift amount)
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Iconst {
                    ty: Type::I32,
                    imm: 4,
                },
                args: vec![],
                results: vec![Value(1)],
            },
            entry,
        )
        .unwrap();

        // The real codegen pipeline pre-scans the function and records every
        // `Iconst` origin (`seed_iconst_origins`); mirror that here so the shift
        // amount `4` is recognised as a compile-time constant.
        isel.iconst_origins.insert(Value(0), (Type::I32, 100));
        isel.iconst_origins.insert(Value(1), (Type::I32, 4));

        // Value(2) = ishl Value(0), Value(1)
        // The shift amount is a known constant in [0, 32), so the immediate
        // shift form is selected directly at isel time (`LSL w,w,#4`).
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Ishl,
                args: vec![Value(0), Value(1)],
                results: vec![Value(2)],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];
        // 1 Movz + 1 Movz + 1 LslRI (immediate form, amount folded as #4).
        assert_eq!(mblock.insts.len(), 3);
        assert_eq!(mblock.insts[2].opcode, AArch64Opcode::LslRI);
        assert_eq!(mblock.insts[2].operands[2], ISelOperand::Imm(4));
    }

    /// A compile-time-constant shift amount in `[0, width)` must lower to the
    /// IMMEDIATE shift form (`LSR/LSL/ASR #imm`), never the variable form, at
    /// BOTH 32- and 64-bit widths. At 64 bits the variable form's opaque
    /// register amount cannot be proven `< 64`, so the per-compile proof gate
    /// rejected `x >> 8` / `x << 8` on `u64`/`i64` until this folding landed.
    /// This pins the EMITTED immediate equals the source constant (the proof
    /// gate verifies opcode semantics but binds operands — this test is what
    /// guarantees operand correctness).
    #[test]
    fn select_shift_constant_amount_uses_immediate_form_both_widths() {
        for (op, expected) in [
            (Opcode::Ushr, AArch64Opcode::LsrRI),
            (Opcode::Ishl, AArch64Opcode::LslRI),
            (Opcode::Sshr, AArch64Opcode::AsrRI),
        ] {
            for width64 in [false, true] {
                let (mut isel, entry) = if width64 {
                    make_i64_isel()
                } else {
                    make_add_isel()
                };
                let src_ty = if width64 { Type::I64 } else { Type::I32 };

                // Reuse the second formal param `Value(1)` as a constant shift
                // amount by recording its `Iconst` origin, exactly as the
                // whole-function pre-scan does for `x >> 8`.
                isel.iconst_origins.insert(Value(1), (src_ty.clone(), 8));

                isel.select_instruction(
                    &Instruction {
                        opcode: op.clone(),
                        args: vec![Value(0), Value(1)],
                        results: vec![Value(2)],
                    },
                    entry,
                )
                .unwrap();

                let mfunc = isel.finalize();
                let mblock = &mfunc.blocks[&entry];
                let shift = mblock
                    .insts
                    .iter()
                    .find(|i| {
                        matches!(
                            i.opcode,
                            AArch64Opcode::LsrRI
                                | AArch64Opcode::LslRI
                                | AArch64Opcode::AsrRI
                                | AArch64Opcode::LsrRR
                                | AArch64Opcode::LslRR
                                | AArch64Opcode::AsrRR
                        )
                    })
                    .expect("a shift instruction was emitted");
                assert_eq!(
                    shift.opcode, expected,
                    "{op:?} on {src_ty:?} must select the immediate shift form"
                );
                assert_eq!(
                    shift.operands[2],
                    ISelOperand::Imm(8),
                    "{op:?} on {src_ty:?} must fold the constant amount as #8"
                );
            }
        }
    }

    /// An OUT-OF-RANGE constant shift amount (a degenerate/UB shift, e.g.
    /// `c >= width`) must NOT be folded into the immediate form: it keeps the
    /// existing register-form behavior so semantics are unchanged.
    #[test]
    fn select_shift_out_of_range_constant_keeps_register_form() {
        let (mut isel, entry) = make_i64_isel();
        // 64 is out of range for a 64-bit shift ([0, 64) is the valid window).
        isel.iconst_origins.insert(Value(1), (Type::I64, 64));
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Ushr,
                args: vec![Value(0), Value(1)],
                results: vec![Value(2)],
            },
            entry,
        )
        .unwrap();
        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];
        // use_value rematerializes the constant and the variable form is used.
        assert!(
            mblock
                .insts
                .iter()
                .any(|i| i.opcode == AArch64Opcode::LsrRR),
            "an out-of-range constant amount must keep the register shift form"
        );
        assert!(
            !mblock
                .insts
                .iter()
                .any(|i| i.opcode == AArch64Opcode::LsrRI),
            "an out-of-range constant amount must NOT use the immediate form"
        );
    }

