    /// A constant operand of a scalar And/Orr/Eor that is a valid AArch64
    /// bitmask immediate is folded into the RI form (`AndRI`/`OrrRI`/`EorRI`)
    /// instead of being materialized into a register and combined with the RR
    /// form. Covers both operand positions (commutativity).
    #[test]
    fn select_logic_folds_encodable_constant_into_ri_form() {
        for (opcode, ri, rr, const_on_rhs) in [
            (
                Opcode::Band,
                AArch64Opcode::AndRI,
                AArch64Opcode::AndRR,
                true,
            ),
            (
                Opcode::Bor,
                AArch64Opcode::OrrRI,
                AArch64Opcode::OrrRR,
                true,
            ),
            (
                Opcode::Bxor,
                AArch64Opcode::EorRI,
                AArch64Opcode::EorRR,
                true,
            ),
            // Commutativity: constant on the LHS folds just the same.
            (
                Opcode::Band,
                AArch64Opcode::AndRI,
                AArch64Opcode::AndRR,
                false,
            ),
        ] {
            let (mut isel, entry) = make_empty_isel();
            isel.current_block = Some(entry);
            let x = Value(0);
            let c = Value(1);
            let result = Value(2);
            let op_dbg = format!("{opcode:?}");
            // `x` is a runtime i32; `c` is the constant 1 (an encodable mask).
            let x_vreg = isel.new_vreg(RegClass::Gpr32);
            isel.define_value(x, ISelOperand::VReg(x_vreg), Type::I32);
            isel.iconst_origins.insert(c, (Type::I32, 1));
            // In the real pipeline the constant's Iconst is selected first, so
            // its type is recorded; mirror that (both operands are i32).
            isel.value_types.insert(c, Type::I32);

            let args = if const_on_rhs { vec![x, c] } else { vec![c, x] };
            isel.select_instruction(
                &Instruction {
                    opcode,
                    args,
                    results: vec![result],
                },
                entry,
            )
            .unwrap();

            let mfunc = isel.finalize();
            let insts = &mfunc.blocks[&entry].insts;
            let ri_inst = insts
                .iter()
                .find(|i| i.opcode == ri)
                .unwrap_or_else(|| panic!("expected {ri:?} for {op_dbg}"));
            assert_eq!(
                ri_inst.operands[2],
                ISelOperand::Imm(1),
                "{op_dbg} should fold immediate 1"
            );
            assert!(
                insts.iter().all(|i| i.opcode != rr),
                "{op_dbg} should not emit the {rr:?} register-register form"
            );
            // The folded constant must not be materialized (no Movz/Movn).
            assert!(
                insts
                    .iter()
                    .all(|i| !matches!(i.opcode, AArch64Opcode::Movz | AArch64Opcode::Movn)),
                "{op_dbg} folded constant must not be materialized"
            );
        }
    }

    /// Fail-closed: a constant that is NOT a valid AArch64 bitmask immediate
    /// (e.g. `0b101 = 5`, which is not a single contiguous rotated run) must
    /// keep the register-register form — emitting `AndRI #5` would be a hard
    /// encoder error.
    #[test]
    fn select_logic_keeps_rr_for_non_encodable_constant() {
        let (mut isel, entry) = make_empty_isel();
        isel.current_block = Some(entry);
        let x = Value(0);
        let c = Value(1);
        let result = Value(2);
        let x_vreg = isel.new_vreg(RegClass::Gpr32);
        isel.define_value(x, ISelOperand::VReg(x_vreg), Type::I32);
        isel.iconst_origins.insert(c, (Type::I32, 5));
        isel.value_types.insert(c, Type::I32);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Band,
                args: vec![x, c],
                results: vec![result],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        assert!(
            insts.iter().any(|i| i.opcode == AArch64Opcode::AndRR),
            "non-encodable immediate must keep the AndRR form"
        );
        assert!(
            insts.iter().all(|i| i.opcode != AArch64Opcode::AndRI),
            "non-encodable immediate must NOT be folded into AndRI"
        );
    }

    /// The `logical_immediate_encodable` predicate must agree with the codegen
    /// encoder's contract at BOTH register widths (a `B1` op is 32-bit-typed
    /// yet lowers into a 64-bit register). Spot-check representative encodable
    /// and non-encodable values.
    #[test]
    fn logical_immediate_encodable_matches_encoder_contract() {
        // Encodable at 32-bit.
        assert!(logical_immediate_encodable(1, true));
        assert!(logical_immediate_encodable(0xff, true));
        assert!(logical_immediate_encodable(0xffff, true));
        assert!(logical_immediate_encodable(0x5555_5555, true));
        assert!(logical_immediate_encodable(0xffff_0000u32 as i64, true));
        // Non-encodable at 32-bit: 5 (0b101 is not a contiguous rotated run),
        // and the all-zeros / all-ones identities.
        assert!(!logical_immediate_encodable(5, true));
        assert!(!logical_immediate_encodable(0, true));
        assert!(!logical_immediate_encodable(0xffff_ffffu32 as i64, true));
        // Width sensitivity: 0x5555_5555 replicates cleanly across 32 bits but
        // NOT across 64 (the high half would be zero, breaking the pattern).
        assert!(!logical_immediate_encodable(0x5555_5555, false));
        assert!(logical_immediate_encodable(
            0x5555_5555_5555_5555u64 as i64,
            false
        ));
        // A single low bit and all-but-one are encodable at 64-bit.
        assert!(logical_immediate_encodable(1, false));
        assert!(!logical_immediate_encodable(0, false));
        assert!(!logical_immediate_encodable(-1, false));
    }

