    #[test]
    fn select_v8i8_pack_lanes_splat_is_single_dup_8b_on_aarch64() {
        let (mut isel, entry) = make_empty_isel();
        // One I8 source, broadcast to all eight byte lanes (a splat —
        // hashbrown's `simd_splat` control-byte broadcast).
        let vreg = isel.new_vreg(RegClass::Gpr32);
        isel.define_value(Value(0), ISelOperand::VReg(vreg), Type::I8);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::V8I8PackLanes,
                args: vec![Value(0); 8],
                results: vec![Value(1)],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        // A splat is exactly one `dup.8b` — no `ins` lanes follow.
        assert_eq!(
            insts.len(),
            1,
            "splat must collapse to a single dup: {insts:?}"
        );
        assert_eq!(insts[0].opcode, AArch64Opcode::NeonDupGen);
        // element_size = 1 (byte) => `.8b` when combined with the Fpr64 dst.
        assert_eq!(insts[0].operands[2], ISelOperand::Imm(1));
        assert!(
            matches!(&insts[0].operands[0], ISelOperand::VReg(vreg) if vreg.class == RegClass::Fpr64),
            "dup destination must be a 64-bit (D) register for `.8b`"
        );
    }

    #[test]
    fn select_v8i8_pack_lanes_distinct_lanes_dup_then_ins_on_aarch64() {
        let (mut isel, entry) = make_empty_isel();
        for lane in 0..8 {
            let vreg = isel.new_vreg(RegClass::Gpr32);
            isel.define_value(Value(lane), ISelOperand::VReg(vreg), Type::I8);
        }

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::V8I8PackLanes,
                args: (0..8).map(Value).collect(),
                results: vec![Value(8)],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        // Non-splat: `dup.8b` of lane 0 then seven `ins` byte lanes.
        assert_eq!(insts.len(), 8);
        assert_eq!(insts[0].opcode, AArch64Opcode::NeonDupGen);
        let dst = insts[0].operands[0].clone();
        assert!(matches!(&dst, ISelOperand::VReg(vreg) if vreg.class == RegClass::Fpr64));
        for (lane, inst) in insts.iter().enumerate().take(8).skip(1) {
            assert_eq!(inst.opcode, AArch64Opcode::NeonInsGen);
            assert_eq!(inst.operands[0], dst);
            assert_eq!(inst.operands[2], ISelOperand::Imm(lane as i64));
            assert_eq!(inst.operands[3], ISelOperand::Imm(1));
        }
    }

