    /// A uniform-constant `<4 x i32>` lane-wise shift lowers to a single NEON
    /// SIMD shift-by-immediate at the 4S arrangement (Imm operand 5), backed by
    /// `proof_vector_{shl,ushr,sshr}_4s`. Right-shift-by-zero is identity and is
    /// emitted as a vector move (`NeonOrrV`), since SHR has no #0 encoding.
    #[test]
    fn select_v4i32_uniform_const_shift_uses_neon_simd_imm_on_aarch64() {
        for (op, count, expected_opcode) in [
            (Opcode::Ishl, 6_i64, AArch64Opcode::NeonShlVImm),
            (Opcode::Ushr, 2, AArch64Opcode::NeonUshrVImm),
            (Opcode::Sshr, 4, AArch64Opcode::NeonSshrVImm),
            (Opcode::Ishl, 0, AArch64Opcode::NeonShlVImm),
        ] {
            let (mut isel, entry) = make_empty_isel();
            // Source vector (the value being shifted).
            let src = isel.new_vreg(RegClass::Fpr128);
            isel.define_value(Value(0), ISelOperand::VReg(src), Type::V128);
            // Four identical constant lanes feeding the pack.
            for lane_val in 1..=4 {
                let r = isel.new_vreg(RegClass::Gpr32);
                isel.define_value(Value(lane_val), ISelOperand::VReg(r), Type::I32);
                isel.iconst_origins
                    .insert(Value(lane_val), (Type::I32, count));
            }
            // Pack the four constant lanes -> Value(5).
            isel.select_instruction(
                &Instruction {
                    opcode: Opcode::V4I32PackLanes,
                    args: vec![Value(1), Value(2), Value(3), Value(4)],
                    results: vec![Value(5)],
                },
                entry,
            )
            .unwrap();
            assert_eq!(
                isel.uniform_v4i32_shift_imm_values.get(&Value(5)),
                Some(&count),
                "pack of uniform const {count} should be tracked"
            );
            // Lane-wise shift: src by the packed uniform count.
            isel.select_instruction(
                &Instruction {
                    opcode: op.clone(),
                    args: vec![Value(0), Value(5)],
                    results: vec![Value(6)],
                },
                entry,
            )
            .unwrap();

            assert_eq!(isel.value_type(&Value(6)), Type::V128);
            let shift_insts: Vec<_> = isel.func.blocks[&entry]
                .insts
                .iter()
                .filter(|i| {
                    matches!(
                        i.opcode,
                        AArch64Opcode::NeonShlVImm
                            | AArch64Opcode::NeonUshrVImm
                            | AArch64Opcode::NeonSshrVImm
                    )
                })
                .collect();
            if matches!(op, Opcode::Ushr | Opcode::Sshr) && count == 0 {
                assert!(shift_insts.is_empty(), "SHR #0 must not emit a shift");
            } else {
                assert_eq!(shift_insts.len(), 1);
                assert_eq!(shift_insts[0].opcode, expected_opcode);
                assert_eq!(shift_insts[0].operands[2], ISelOperand::Imm(count));
                assert_eq!(shift_insts[0].operands[3], ISelOperand::Imm(5)); // 4S
            }
        }
    }

    /// A `<4 x i32>` shift by a runtime (non-constant) vector count lowers
    /// LANE-WISE through a stack round-trip using the proven scalar shift-by-
    /// register op (LSLV/LSRV/ASRV) — four scalar shifts, one per lane — rather
    /// than failing closed or mis-emitting a scalar shift over an FPR128.
    /// Execution-verified separately ({1,2,4,8}<<{0,1,2,3} == {1,4,16,64}).
    #[test]
    fn select_v4i32_variable_shift_lowers_lane_wise_on_aarch64() {
        let (mut isel, entry) = make_empty_isel();
        let src = isel.new_vreg(RegClass::Fpr128);
        let amt = isel.new_vreg(RegClass::Fpr128);
        isel.define_value(Value(0), ISelOperand::VReg(src), Type::V128);
        // No iconst origins / no tracked uniform-const pack: a runtime count.
        isel.define_value(Value(1), ISelOperand::VReg(amt), Type::V128);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Ishl,
                args: vec![Value(0), Value(1)],
                results: vec![Value(2)],
            },
            entry,
        )
        .expect("variable V128 shift now lowers lane-wise");

        let insts = &isel.func.blocks[&entry].insts;
        // Exactly four scalar shift-by-register ops (one per lane).
        let lslv_count = insts
            .iter()
            .filter(|i| i.opcode == AArch64Opcode::LslRR)
            .count();
        assert_eq!(
            lslv_count, 4,
            "packed shl -> four scalar LSLV, got {lslv_count}"
        );
        // No packed NEON shift-by-immediate (that path is the uniform-const case).
        assert!(
            !insts.iter().any(|i| i.opcode == AArch64Opcode::NeonShlVImm),
            "variable shift must not use the uniform-const NEON immediate path"
        );
    }

    #[test]
    fn select_v2i64_mul_scalarizes_lanes_on_aarch64() {
        let (mut isel, entry) = make_empty_isel();
        let lhs = isel.new_vreg(RegClass::Fpr128);
        let rhs = isel.new_vreg(RegClass::Fpr128);
        isel.define_value(Value(0), ISelOperand::VReg(lhs), Type::V128);
        isel.define_value(Value(1), ISelOperand::VReg(rhs), Type::V128);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::V2I64Mul,
                args: vec![Value(0), Value(1)],
                results: vec![Value(2)],
            },
            entry,
        )
        .unwrap();

        assert_eq!(isel.value_type(&Value(2)), Type::V128);
        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        assert_eq!(
            insts
                .iter()
                .filter(|inst| inst.opcode == AArch64Opcode::NeonUmovGen)
                .count(),
            4
        );
        assert_eq!(
            insts
                .iter()
                .filter(|inst| inst.opcode == AArch64Opcode::MulRR)
                .count(),
            2
        );
        assert_eq!(insts[6].opcode, AArch64Opcode::NeonDupGen);
        assert_eq!(insts[7].opcode, AArch64Opcode::NeonInsGen);
        assert!(
            insts
                .iter()
                .all(|inst| inst.opcode != AArch64Opcode::NeonMulV)
        );
    }

