    #[test]
    fn select_csel_i32() {
        let sig = Signature {
            params: vec![Type::I32, Type::I32, Type::I32],
            returns: vec![Type::I32],
        };
        let mut isel = InstructionSelector::new("csel".to_string(), sig.clone());
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();

        // Value(3) = select(NE, Value(0), Value(1), Value(2))
        // cond_val=Value(0), true=Value(1), false=Value(2)
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Select {
                    cond: IntCC::NotEqual,
                },
                args: vec![Value(0), Value(1), Value(2)],
                results: vec![Value(3)],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];
        // 3 COPY (args) + 1 CmpRI + 1 Csel
        assert_eq!(mblock.insts.len(), 5);
        assert_eq!(mblock.insts[3].opcode, AArch64Opcode::CmpRI);
        assert_eq!(mblock.insts[4].opcode, AArch64Opcode::Csel);
        assert_eq!(
            mblock.insts[4].operands[3],
            ISelOperand::CondCode(AArch64CC::NE)
        );
    }

    #[test]
    fn select_csel_i64() {
        let sig = Signature {
            params: vec![Type::I32, Type::I64, Type::I64],
            returns: vec![Type::I64],
        };
        let mut isel = InstructionSelector::new("csel64".to_string(), sig.clone());
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Select {
                    cond: IntCC::SignedGreaterThan,
                },
                args: vec![Value(0), Value(1), Value(2)],
                results: vec![Value(3)],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];
        // 3 COPY + 1 CmpRI + 1 Csel (64-bit because true_val is I64)
        assert_eq!(mblock.insts[4].opcode, AArch64Opcode::Csel);
        assert_eq!(
            mblock.insts[4].operands[3],
            ISelOperand::CondCode(AArch64CC::GT)
        );
    }

    /// FP `Select` over f32/f64 lowers to `CMP cond,#0` + a single FPR-domain
    /// `FCSEL` — NOT the old FMOV(FPR->GPR)x2 + integer CSEL + FMOV(GPR->FPR)
    /// cross-bank route. No FMOV bank-crossing move appears at all.
    #[test]
    fn select_fp_select_f32_and_f64_use_fcsel() {
        for (fty, cond, expect_cc) in [
            (Type::F32, IntCC::NotEqual, AArch64CC::NE),
            (Type::F64, IntCC::SignedLessThan, AArch64CC::LT),
        ] {
            let sig = Signature {
                params: vec![Type::I32, fty.clone(), fty.clone()],
                returns: vec![fty.clone()],
            };
            let mut isel = InstructionSelector::new("fpsel".to_string(), sig.clone());
            let entry = Block(0);
            isel.lower_formal_arguments(&sig, entry).unwrap();

            isel.select_instruction(
                &Instruction {
                    opcode: Opcode::Select { cond },
                    args: vec![Value(0), Value(1), Value(2)],
                    results: vec![Value(3)],
                },
                entry,
            )
            .unwrap();

            let mfunc = isel.finalize();
            let insts = &mfunc.blocks[&entry].insts;
            // Exactly one CmpRI then one FcselRR; no cross-bank FMOVs.
            let cmp_pos = insts
                .iter()
                .position(|i| i.opcode == AArch64Opcode::CmpRI)
                .expect("expected a CmpRI");
            assert_eq!(
                insts[cmp_pos + 1].opcode,
                AArch64Opcode::FcselRR,
                "FP select ({fty:?}) must lower CMP then FCSEL"
            );
            assert_eq!(
                insts[cmp_pos + 1].operands[3],
                ISelOperand::CondCode(expect_cc)
            );
            assert!(
                insts.iter().all(|i| i.opcode != AArch64Opcode::FmovFprGpr
                    && i.opcode != AArch64Opcode::FmovGprFpr),
                "FP select ({fty:?}) must NOT emit any cross-bank FMOV"
            );
            assert!(
                insts.iter().all(|i| i.opcode != AArch64Opcode::Csel),
                "FP select ({fty:?}) must NOT emit an integer CSEL"
            );
        }
    }

    // =======================================================================
    // Flags-consuming compare folding (icmp -> C/FCSEL)
    // =======================================================================

    /// Count opcode occurrences in a finalized block.
    fn fold_count(insts: &[ISelInst], op: AArch64Opcode) -> usize {
        insts.iter().filter(|i| i.opcode == op).count()
    }

    /// FP `Select` of `(x <slt y) ? a : b` where `x<y` is single-use: the icmp
    /// is elided (no CSET, no materialized i1) and the select re-emits `CMP x,y`
    /// straight into the FCSEL's `LT` — no `CMP cond,#0` round trip.
    #[test]
    fn select_fold_icmp_regreg_into_fcsel() {
        let sig = Signature {
            params: vec![Type::I32, Type::I32, Type::F64, Type::F64],
            returns: vec![Type::F64],
        };
        let mut isel = InstructionSelector::new("fold_rr".to_string(), sig.clone());
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();
        let instructions = vec![
            Instruction {
                opcode: Opcode::Icmp {
                    cond: IntCC::SignedLessThan,
                },
                args: vec![Value(0), Value(1)],
                results: vec![Value(4)],
            },
            Instruction {
                opcode: Opcode::Select {
                    cond: IntCC::NotEqual,
                },
                args: vec![Value(4), Value(2), Value(3)],
                results: vec![Value(5)],
            },
            Instruction {
                opcode: Opcode::Return,
                args: vec![Value(5)],
                results: vec![],
            },
        ];
        isel.select_block(entry, &instructions).unwrap();
        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;

        assert_eq!(
            fold_count(insts, AArch64Opcode::CSet),
            0,
            "cset must be elided"
        );
        assert_eq!(
            fold_count(insts, AArch64Opcode::CmpRR),
            1,
            "exactly one CMP reg,reg feeds the FCSEL"
        );
        // No `CMP cond,#0` re-test: the only compare is the reg-reg one.
        assert_eq!(fold_count(insts, AArch64Opcode::CmpRI), 0);
        let fcsel = insts
            .iter()
            .find(|i| i.opcode == AArch64Opcode::FcselRR)
            .expect("expected an FCSEL");
        assert_eq!(fcsel.operands[3], ISelOperand::CondCode(AArch64CC::LT));
        // CMP must be immediately before the FCSEL (fresh flags).
        let cmp_pos = insts
            .iter()
            .position(|i| i.opcode == AArch64Opcode::CmpRR)
            .unwrap();
        let fcsel_pos = insts
            .iter()
            .position(|i| i.opcode == AArch64Opcode::FcselRR)
            .unwrap();
        assert_eq!(cmp_pos + 1, fcsel_pos, "CMP must directly precede FCSEL");
    }

    /// FP `Select` of `(x <slt 8) ? a : b`: the immediate compare RHS folds to
    /// `CMP x,#8` (reg-imm), not a materialized register.
    #[test]
    fn select_fold_icmp_regimm_into_fcsel() {
        let sig = Signature {
            params: vec![Type::I32, Type::F64, Type::F64],
            returns: vec![Type::F64],
        };
        let mut isel = InstructionSelector::new("fold_ri".to_string(), sig.clone());
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();
        let instructions = vec![
            Instruction {
                opcode: Opcode::Iconst {
                    ty: Type::I32,
                    imm: 8,
                },
                args: vec![],
                results: vec![Value(3)],
            },
            Instruction {
                opcode: Opcode::Icmp {
                    cond: IntCC::SignedLessThan,
                },
                args: vec![Value(0), Value(3)],
                results: vec![Value(4)],
            },
            Instruction {
                opcode: Opcode::Select {
                    cond: IntCC::NotEqual,
                },
                args: vec![Value(4), Value(1), Value(2)],
                results: vec![Value(5)],
            },
            Instruction {
                opcode: Opcode::Return,
                args: vec![Value(5)],
                results: vec![],
            },
        ];
        isel.select_block(entry, &instructions).unwrap();
        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;

        assert_eq!(fold_count(insts, AArch64Opcode::CSet), 0);
        let cmp = insts
            .iter()
            .find(|i| i.opcode == AArch64Opcode::CmpRI)
            .expect("expected CMP reg,#imm");
        assert_eq!(cmp.operands[1], ISelOperand::Imm(8), "CMP #8");
        let fcsel = insts
            .iter()
            .find(|i| i.opcode == AArch64Opcode::FcselRR)
            .expect("expected an FCSEL");
        assert_eq!(fcsel.operands[3], ISelOperand::CondCode(AArch64CC::LT));
    }

    /// A `Select{Eq}` (pick true when the i1 is FALSE) inverts the folded code:
    /// `(x <slt y)` compares to `LT`, but `Select{Eq}` folds it to `GE`.
    #[test]
    fn select_fold_eq_select_inverts_cc() {
        let sig = Signature {
            params: vec![Type::I32, Type::I32, Type::I64, Type::I64],
            returns: vec![Type::I64],
        };
        let mut isel = InstructionSelector::new("fold_eq".to_string(), sig.clone());
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();
        let instructions = vec![
            Instruction {
                opcode: Opcode::Icmp {
                    cond: IntCC::SignedLessThan,
                },
                args: vec![Value(0), Value(1)],
                results: vec![Value(4)],
            },
            Instruction {
                opcode: Opcode::Select { cond: IntCC::Equal },
                args: vec![Value(4), Value(2), Value(3)],
                results: vec![Value(5)],
            },
            Instruction {
                opcode: Opcode::Return,
                args: vec![Value(5)],
                results: vec![],
            },
        ];
        isel.select_block(entry, &instructions).unwrap();
        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;

        assert_eq!(fold_count(insts, AArch64Opcode::CSet), 0);
        let csel = insts
            .iter()
            .find(|i| i.opcode == AArch64Opcode::Csel)
            .expect("expected a CSEL");
        assert_eq!(
            csel.operands[3],
            ISelOperand::CondCode(AArch64CC::GE),
            "Select{{Eq}} inverts LT -> GE"
        );
    }

    /// Multi-use RELAXATION: when the compare feeds ONLY selects that this pass
    /// folds (each re-emits its own compare), the shared compare is elided even
    /// though it has >1 use. No `CSET` is materialized; each select re-emits the
    /// `CMP`. (Was previously fail-closed; the relaxation is the idamax lever.)
    #[test]
    fn select_fold_multi_use_all_folded_selects_elides_compare() {
        let sig = Signature {
            params: vec![Type::I32, Type::I32, Type::I64, Type::I64],
            returns: vec![Type::I64],
        };
        let mut isel = InstructionSelector::new("fold_multi".to_string(), sig.clone());
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();
        let instructions = vec![
            Instruction {
                opcode: Opcode::Icmp {
                    cond: IntCC::SignedLessThan,
                },
                args: vec![Value(0), Value(1)],
                results: vec![Value(4)],
            },
            Instruction {
                opcode: Opcode::Select {
                    cond: IntCC::NotEqual,
                },
                args: vec![Value(4), Value(2), Value(3)],
                results: vec![Value(5)],
            },
            Instruction {
                opcode: Opcode::Select {
                    cond: IntCC::NotEqual,
                },
                args: vec![Value(4), Value(3), Value(2)],
                results: vec![Value(6)],
            },
            Instruction {
                opcode: Opcode::Iadd,
                args: vec![Value(5), Value(6)],
                results: vec![Value(7)],
            },
            Instruction {
                opcode: Opcode::Return,
                args: vec![Value(7)],
                results: vec![],
            },
        ];
        isel.select_block(entry, &instructions).unwrap();
        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;

        // Both selects fold: the icmp is elided (no CSET), each select re-emits
        // its own `CMP x,y` (LT), and no `CMP cond,#0` retest remains.
        assert_eq!(
            fold_count(insts, AArch64Opcode::CSet),
            0,
            "shared compare elided: no materialized i1"
        );
        assert_eq!(
            fold_count(insts, AArch64Opcode::Csel),
            2,
            "both selects present"
        );
        assert_eq!(
            fold_count(insts, AArch64Opcode::CmpRR),
            2,
            "each select re-emits the reg-reg compare"
        );
        assert_eq!(
            fold_count(insts, AArch64Opcode::CmpRI),
            0,
            "no CMP cond,#0 retest"
        );
    }

    /// Multi-use still fail-closed when a NON-fold use exists: here the compare
    /// result also feeds an `Iadd` (a data use), so eliding its def would leave
    /// that read dangling. The i1 is materialized and neither select folds.
    #[test]
    fn select_fold_multi_use_bails_on_data_use() {
        let sig = Signature {
            params: vec![Type::I32, Type::I32, Type::I64, Type::I64],
            returns: vec![Type::I64],
        };
        let mut isel = InstructionSelector::new("fold_multi_data".to_string(), sig.clone());
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();
        let instructions = vec![
            Instruction {
                opcode: Opcode::Icmp {
                    cond: IntCC::SignedLessThan,
                },
                args: vec![Value(0), Value(1)],
                results: vec![Value(4)],
            },
            Instruction {
                opcode: Opcode::Select {
                    cond: IntCC::NotEqual,
                },
                args: vec![Value(4), Value(2), Value(3)],
                results: vec![Value(5)],
            },
            // A DATA use of the i1 (arithmetic, not a select condition): the
            // relaxation must NOT fire, keeping the materialized CSET route.
            Instruction {
                opcode: Opcode::Iadd,
                args: vec![Value(4), Value(5)],
                results: vec![Value(6)],
            },
            Instruction {
                opcode: Opcode::Return,
                args: vec![Value(6)],
                results: vec![],
            },
        ];
        isel.select_block(entry, &instructions).unwrap();
        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;

        assert_eq!(
            fold_count(insts, AArch64Opcode::CSet),
            1,
            "data-used i1 must be materialized"
        );
        assert!(
            fold_count(insts, AArch64Opcode::CmpRI) >= 1,
            "the select re-tests cond,#0 (no fold)"
        );
    }

    /// A single-CC `fcmp ogt` feeding an FP `Select{Ne}` folds: the `Fcmp` is
    /// elided (no CSET materialization of the i1), the select re-emits `FCMP`
    /// straight into the FCSEL's `GT` — no `CMP cond,#0` round trip.
    #[test]
    fn select_fold_fcmp_ogt_single_use_into_fcsel() {
        let sig = Signature {
            params: vec![Type::F64, Type::F64, Type::F64, Type::F64],
            returns: vec![Type::F64],
        };
        let mut isel = InstructionSelector::new("fold_fcmp".to_string(), sig.clone());
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();
        let instructions = vec![
            Instruction {
                opcode: Opcode::Fcmp {
                    cond: FloatCC::GreaterThan,
                },
                args: vec![Value(0), Value(1)],
                results: vec![Value(4)],
            },
            Instruction {
                opcode: Opcode::Select {
                    cond: IntCC::NotEqual,
                },
                args: vec![Value(4), Value(2), Value(3)],
                results: vec![Value(5)],
            },
            Instruction {
                opcode: Opcode::Return,
                args: vec![Value(5)],
                results: vec![],
            },
        ];
        isel.select_block(entry, &instructions).unwrap();
        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;

        assert_eq!(
            fold_count(insts, AArch64Opcode::CSet),
            0,
            "no materialized i1"
        );
        assert_eq!(
            fold_count(insts, AArch64Opcode::Fcmp),
            1,
            "exactly one FCMP feeds the FCSEL"
        );
        assert_eq!(fold_count(insts, AArch64Opcode::CmpRI), 0, "no CMP cond,#0");
        let fcsel = insts
            .iter()
            .find(|i| i.opcode == AArch64Opcode::FcselRR)
            .expect("expected an FCSEL");
        assert_eq!(fcsel.operands[3], ISelOperand::CondCode(AArch64CC::GT));
        // FCMP must directly precede the FCSEL (fresh flags).
        let fcmp_pos = insts
            .iter()
            .position(|i| i.opcode == AArch64Opcode::Fcmp)
            .unwrap();
        let fcsel_pos = insts
            .iter()
            .position(|i| i.opcode == AArch64Opcode::FcselRR)
            .unwrap();
        assert_eq!(fcmp_pos + 1, fcsel_pos, "FCMP must directly precede FCSEL");
    }

    /// The `Eq`-sense of an `fcmp ogt` select folds to the COMPLEMENT code (LE),
    /// which is correctly TRUE for NaN (`!ogt` = `ole || unordered`).
    #[test]
    fn select_fold_fcmp_eq_sense_inverts_to_le() {
        let sig = Signature {
            params: vec![Type::F64, Type::F64, Type::F64, Type::F64],
            returns: vec![Type::F64],
        };
        let mut isel = InstructionSelector::new("fold_fcmp_eq".to_string(), sig.clone());
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();
        let instructions = vec![
            Instruction {
                opcode: Opcode::Fcmp {
                    cond: FloatCC::GreaterThan,
                },
                args: vec![Value(0), Value(1)],
                results: vec![Value(4)],
            },
            Instruction {
                opcode: Opcode::Select { cond: IntCC::Equal },
                args: vec![Value(4), Value(2), Value(3)],
                results: vec![Value(5)],
            },
            Instruction {
                opcode: Opcode::Return,
                args: vec![Value(5)],
                results: vec![],
            },
        ];
        isel.select_block(entry, &instructions).unwrap();
        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        assert_eq!(fold_count(insts, AArch64Opcode::CSet), 0);
        let fcsel = insts
            .iter()
            .find(|i| i.opcode == AArch64Opcode::FcselRR)
            .expect("expected an FCSEL");
        assert_eq!(
            fcsel.operands[3],
            ISelOperand::CondCode(AArch64CC::LE),
            "Select{{Eq}} inverts GT -> LE (NaN-true)"
        );
    }

    /// The two-CC FloatCCs (`One`, `UnorderedEqual`) MUST NOT fold — folding to
    /// their single primary code would mishandle NaN. The `Fcmp` stays
    /// materialized (its two-CC CSET sequence present) and the select re-tests
    /// `CMP cond,#0`.
    #[test]
    fn select_fold_fcmp_two_cc_one_bails() {
        for cc in [FloatCC::NotEqual, FloatCC::UnorderedEqual] {
            let sig = Signature {
                params: vec![Type::F64, Type::F64, Type::F64, Type::F64],
                returns: vec![Type::F64],
            };
            let mut isel = InstructionSelector::new("fold_fcmp_2cc".to_string(), sig.clone());
            let entry = Block(0);
            isel.lower_formal_arguments(&sig, entry).unwrap();
            let instructions = vec![
                Instruction {
                    opcode: Opcode::Fcmp { cond: cc },
                    args: vec![Value(0), Value(1)],
                    results: vec![Value(4)],
                },
                Instruction {
                    opcode: Opcode::Select {
                        cond: IntCC::NotEqual,
                    },
                    args: vec![Value(4), Value(2), Value(3)],
                    results: vec![Value(5)],
                },
                Instruction {
                    opcode: Opcode::Return,
                    args: vec![Value(5)],
                    results: vec![],
                },
            ];
            isel.select_block(entry, &instructions).unwrap();
            let mfunc = isel.finalize();
            let insts = &mfunc.blocks[&entry].insts;
            // Two-CC materialization present (the fold did NOT fire): the i1 is
            // built via CSETs and the select re-tests it with CMP cond,#0.
            assert!(
                fold_count(insts, AArch64Opcode::CSet) >= 2,
                "{cc:?}: two-CC i1 must be materialized (no fold)"
            );
            assert!(
                fold_count(insts, AArch64Opcode::CmpRI) >= 1,
                "{cc:?}: select re-tests cond,#0 (no fold)"
            );
        }
    }

    /// The idamax shape: one `fcmp ogt` feeds BOTH an f64 select (the running
    /// max, an FCSEL) and an i64 select (its index, a CSEL). The multi-use
    /// relaxation folds both: the `Fcmp` is elided (no CSET), each select
    /// re-emits its own `FCMP` into a `GT`-conditioned F/CSEL.
    #[test]
    fn select_fold_fcmp_multiuse_idamax_fcsel_and_csel() {
        let sig = Signature {
            params: vec![Type::F64, Type::F64, Type::F64, Type::I64, Type::I64],
            returns: vec![Type::I64],
        };
        let mut isel = InstructionSelector::new("fold_idamax".to_string(), sig.clone());
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();
        let instructions = vec![
            // c = x > dmax   (ordered)
            Instruction {
                opcode: Opcode::Fcmp {
                    cond: FloatCC::GreaterThan,
                },
                args: vec![Value(0), Value(1)],
                results: vec![Value(5)],
            },
            // dmax' = c ? x : dmax      (FCSEL, f64)
            Instruction {
                opcode: Opcode::Select {
                    cond: IntCC::NotEqual,
                },
                args: vec![Value(5), Value(0), Value(2)],
                results: vec![Value(6)],
            },
            // idx'  = c ? i : idx       (CSEL, i64)
            Instruction {
                opcode: Opcode::Select {
                    cond: IntCC::NotEqual,
                },
                args: vec![Value(5), Value(4), Value(3)],
                results: vec![Value(7)],
            },
            // keep both selects live: fold dmax' to int and add the index.
            Instruction {
                opcode: Opcode::FcvtToInt { dst_ty: Type::I64 },
                args: vec![Value(6)],
                results: vec![Value(8)],
            },
            Instruction {
                opcode: Opcode::Iadd,
                args: vec![Value(8), Value(7)],
                results: vec![Value(9)],
            },
            Instruction {
                opcode: Opcode::Return,
                args: vec![Value(9)],
                results: vec![],
            },
        ];
        isel.select_block(entry, &instructions).unwrap();
        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;

        // Both selects fold: the fcmp result is never materialized (no CSET),
        // and each select re-emits its own FCMP directly before its F/CSEL.
        assert_eq!(
            fold_count(insts, AArch64Opcode::CSet),
            0,
            "shared fcmp elided: no materialized i1"
        );
        assert_eq!(
            fold_count(insts, AArch64Opcode::Fcmp),
            2,
            "each folded select re-emits its own FCMP"
        );
        assert_eq!(
            fold_count(insts, AArch64Opcode::FcselRR),
            1,
            "the f64 max FCSEL"
        );
        assert_eq!(
            fold_count(insts, AArch64Opcode::Csel),
            1,
            "the i64 index CSEL"
        );
        assert_eq!(
            fold_count(insts, AArch64Opcode::CmpRI),
            0,
            "no CMP cond,#0 retest"
        );
        // Every F/CSEL is directly preceded by its re-emitted FCMP and tests GT.
        for (pos, inst) in insts.iter().enumerate() {
            if matches!(inst.opcode, AArch64Opcode::FcselRR | AArch64Opcode::Csel) {
                assert_eq!(
                    insts[pos - 1].opcode,
                    AArch64Opcode::Fcmp,
                    "F/CSEL directly preceded by its FCMP"
                );
                assert_eq!(inst.operands[3], ISelOperand::CondCode(AArch64CC::GT));
            }
        }
    }

    /// `(a & b) == 0` with a VARIABLE mask folds to a single `TST a,b` feeding
    /// the FCSEL's `EQ`: both the `Band` and the `Icmp` are elided.
    #[test]
    fn select_fold_and_eq_zero_variable_mask_uses_tst() {
        let sig = Signature {
            params: vec![Type::I32, Type::I32, Type::F64, Type::F64],
            returns: vec![Type::F64],
        };
        let mut isel = InstructionSelector::new("fold_tst".to_string(), sig.clone());
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();
        let instructions = vec![
            Instruction {
                opcode: Opcode::Iconst {
                    ty: Type::I32,
                    imm: 0,
                },
                args: vec![],
                results: vec![Value(4)],
            },
            Instruction {
                opcode: Opcode::Band,
                args: vec![Value(0), Value(1)],
                results: vec![Value(5)],
            },
            Instruction {
                opcode: Opcode::Icmp { cond: IntCC::Equal },
                args: vec![Value(5), Value(4)],
                results: vec![Value(6)],
            },
            Instruction {
                opcode: Opcode::Select {
                    cond: IntCC::NotEqual,
                },
                args: vec![Value(6), Value(2), Value(3)],
                results: vec![Value(7)],
            },
            Instruction {
                opcode: Opcode::Return,
                args: vec![Value(7)],
                results: vec![],
            },
        ];
        isel.select_block(entry, &instructions).unwrap();
        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;

        assert_eq!(fold_count(insts, AArch64Opcode::Tst), 1, "one TST a,b");
        assert_eq!(
            fold_count(insts, AArch64Opcode::AndRR),
            0,
            "the Band is elided into the TST"
        );
        assert_eq!(fold_count(insts, AArch64Opcode::CSet), 0);
        assert_eq!(fold_count(insts, AArch64Opcode::CmpRI), 0);
        let fcsel = insts
            .iter()
            .find(|i| i.opcode == AArch64Opcode::FcselRR)
            .expect("expected an FCSEL");
        assert_eq!(fcsel.operands[3], ISelOperand::CondCode(AArch64CC::EQ));
    }

    /// `(a & 8) == 0` with a CONSTANT mask keeps the `AND` (there is no modeled
    /// TST-immediate opcode) but still folds the `== 0` compare: the CSET and
    /// the select-side `CMP cond,#0` are elided, leaving `AND` + `CMP #0` +
    /// FCSEL(EQ).
    #[test]
    fn select_fold_and_eq_zero_const_mask_keeps_and() {
        let sig = Signature {
            params: vec![Type::I32, Type::F64, Type::F64],
            returns: vec![Type::F64],
        };
        let mut isel = InstructionSelector::new("fold_andc".to_string(), sig.clone());
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();
        let instructions = vec![
            Instruction {
                opcode: Opcode::Iconst {
                    ty: Type::I32,
                    imm: 8,
                },
                args: vec![],
                results: vec![Value(3)],
            },
            Instruction {
                opcode: Opcode::Iconst {
                    ty: Type::I32,
                    imm: 0,
                },
                args: vec![],
                results: vec![Value(4)],
            },
            Instruction {
                opcode: Opcode::Band,
                args: vec![Value(0), Value(3)],
                results: vec![Value(5)],
            },
            Instruction {
                opcode: Opcode::Icmp { cond: IntCC::Equal },
                args: vec![Value(5), Value(4)],
                results: vec![Value(6)],
            },
            Instruction {
                opcode: Opcode::Select {
                    cond: IntCC::NotEqual,
                },
                args: vec![Value(6), Value(1), Value(2)],
                results: vec![Value(7)],
            },
            Instruction {
                opcode: Opcode::Return,
                args: vec![Value(7)],
                results: vec![],
            },
        ];
        isel.select_block(entry, &instructions).unwrap();
        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;

        assert_eq!(
            fold_count(insts, AArch64Opcode::Tst),
            0,
            "no TST-imm modeled"
        );
        // The `Band` survives (const mask cannot use the reg-reg TST fold);
        // `select_logic` materializes it as AND reg,reg.
        assert_eq!(
            fold_count(insts, AArch64Opcode::AndRR) + fold_count(insts, AArch64Opcode::AndRI),
            1,
            "the AND survives the compare fold"
        );
        assert_eq!(fold_count(insts, AArch64Opcode::CSet), 0);
        // Exactly one CMP #0 (folded), directly before the FCSEL.
        let cmp = insts
            .iter()
            .find(|i| i.opcode == AArch64Opcode::CmpRI)
            .expect("expected CMP #0");
        assert_eq!(cmp.operands[1], ISelOperand::Imm(0));
        let fcsel = insts
            .iter()
            .find(|i| i.opcode == AArch64Opcode::FcselRR)
            .expect("expected an FCSEL");
        assert_eq!(fcsel.operands[3], ISelOperand::CondCode(AArch64CC::EQ));
    }

    /// The re-emit design captures a select whose i1's compare is separated from
    /// it by a FLAG-WRITER (another icmp+select). This is the perlin `h<4`
    /// outer-select shape that a live-flag-reuse design would have to forfeit.
    /// Both selects fold; no CSET is materialized for either.
    #[test]
    fn select_fold_fires_through_intervening_flag_writer() {
        let sig = Signature {
            params: vec![Type::I32, Type::I32, Type::F64, Type::F64],
            returns: vec![Type::F64],
        };
        let mut isel = InstructionSelector::new("fold_between".to_string(), sig.clone());
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();
        let instructions = vec![
            // c1 = x < y      (feeds sel2, defined FIRST)
            Instruction {
                opcode: Opcode::Icmp {
                    cond: IntCC::SignedLessThan,
                },
                args: vec![Value(0), Value(1)],
                results: vec![Value(4)],
            },
            // c2 = x > y      (a flag-writer BETWEEN c1 and its select)
            Instruction {
                opcode: Opcode::Icmp {
                    cond: IntCC::SignedGreaterThan,
                },
                args: vec![Value(0), Value(1)],
                results: vec![Value(5)],
            },
            // sel1 = c2 ? a : b
            Instruction {
                opcode: Opcode::Select {
                    cond: IntCC::NotEqual,
                },
                args: vec![Value(5), Value(2), Value(3)],
                results: vec![Value(6)],
            },
            // sel2 = c1 ? sel1 : b   (c1 folded despite c2/sel1 in between)
            Instruction {
                opcode: Opcode::Select {
                    cond: IntCC::NotEqual,
                },
                args: vec![Value(4), Value(6), Value(3)],
                results: vec![Value(7)],
            },
            Instruction {
                opcode: Opcode::Return,
                args: vec![Value(7)],
                results: vec![],
            },
        ];
        isel.select_block(entry, &instructions).unwrap();
        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;

        // Both compares fold: no CSET anywhere, two CMP reg,reg (one re-emitted
        // at each select), each directly preceding its FCSEL.
        assert_eq!(
            fold_count(insts, AArch64Opcode::CSet),
            0,
            "re-emit folds even through an intervening flag-writer"
        );
        assert_eq!(fold_count(insts, AArch64Opcode::FcselRR), 2);
        assert_eq!(fold_count(insts, AArch64Opcode::CmpRR), 2);
        for pos in insts
            .iter()
            .enumerate()
            .filter(|(_, i)| i.opcode == AArch64Opcode::FcselRR)
            .map(|(p, _)| p)
        {
            assert_eq!(
                insts[pos - 1].opcode,
                AArch64Opcode::CmpRR,
                "each FCSEL is directly preceded by its re-emitted CMP"
            );
        }
    }

    /// Every IntCC predicate folds to the matching AArch64 code under a
    /// `Select{Ne}` (which passes the compare's code through unchanged).
    #[test]
    fn select_fold_cc_mapping_all_predicates() {
        for (icc, expect) in [
            (IntCC::Equal, AArch64CC::EQ),
            (IntCC::NotEqual, AArch64CC::NE),
            (IntCC::SignedLessThan, AArch64CC::LT),
            (IntCC::SignedGreaterThanOrEqual, AArch64CC::GE),
            (IntCC::SignedGreaterThan, AArch64CC::GT),
            (IntCC::SignedLessThanOrEqual, AArch64CC::LE),
            (IntCC::UnsignedLessThan, AArch64CC::LO),
            (IntCC::UnsignedGreaterThanOrEqual, AArch64CC::HS),
            (IntCC::UnsignedGreaterThan, AArch64CC::HI),
            (IntCC::UnsignedLessThanOrEqual, AArch64CC::LS),
        ] {
            let sig = Signature {
                params: vec![Type::I32, Type::I32, Type::I64, Type::I64],
                returns: vec![Type::I64],
            };
            let mut isel = InstructionSelector::new("fold_cc".to_string(), sig.clone());
            let entry = Block(0);
            isel.lower_formal_arguments(&sig, entry).unwrap();
            let instructions = vec![
                Instruction {
                    opcode: Opcode::Icmp { cond: icc },
                    args: vec![Value(0), Value(1)],
                    results: vec![Value(4)],
                },
                Instruction {
                    opcode: Opcode::Select {
                        cond: IntCC::NotEqual,
                    },
                    args: vec![Value(4), Value(2), Value(3)],
                    results: vec![Value(5)],
                },
                Instruction {
                    opcode: Opcode::Return,
                    args: vec![Value(5)],
                    results: vec![],
                },
            ];
            isel.select_block(entry, &instructions).unwrap();
            let mfunc = isel.finalize();
            let insts = &mfunc.blocks[&entry].insts;
            assert_eq!(fold_count(insts, AArch64Opcode::CSet), 0, "{icc:?}");
            let csel = insts
                .iter()
                .find(|i| i.opcode == AArch64Opcode::Csel)
                .expect("expected a CSEL");
            assert_eq!(csel.operands[3], ISelOperand::CondCode(expect), "{icc:?}");
        }
    }

