    #[test]
    fn select_fma_emits_fmadd_with_abc_operand_order() {
        // Fma(a, b, c) = a*b + c -> FMADD Rd, Rn=a, Rm=b, Ra=c.
        let sig = Signature {
            params: vec![Type::F64, Type::F64, Type::F64],
            returns: vec![Type::F64],
        };
        let mut isel = InstructionSelector::new("fma".to_string(), sig.clone());
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Fma,
                args: vec![Value(0), Value(1), Value(2)],
                results: vec![Value(3)],
            },
            entry,
        )
        .unwrap();
        let mfunc = isel.finalize();
        // 3 formal-arg copies + the FMADD.
        let fmadd = mfunc.blocks[&entry]
            .insts
            .iter()
            .find(|i| i.opcode == AArch64Opcode::FmaddRR)
            .expect("must emit FmaddRR");
        // [Rd, Rn, Rm, Ra] — 4 operands, all FP registers.
        assert_eq!(fmadd.operands.len(), 4, "FMADD is a 4-operand FP inst");
        assert!(
            !fmadd.fmuladd_may_unfuse,
            "strict Opcode::Fma must not carry the optional-fusion contract"
        );
    }

    #[test]
    fn select_fmuladd_marks_machine_instruction_as_fusion_licensed() {
        let sig = Signature {
            params: vec![Type::F64, Type::F64, Type::F64],
            returns: vec![Type::F64],
        };
        let mut isel = InstructionSelector::new("fmuladd".to_string(), sig.clone());
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Fmuladd,
                args: vec![Value(0), Value(1), Value(2)],
                results: vec![Value(3)],
            },
            entry,
        )
        .unwrap();
        let selected = isel.finalize();
        let fmadd = selected.blocks[&entry]
            .insts
            .iter()
            .find(|inst| inst.opcode == AArch64Opcode::FmaddRR)
            .expect("must emit FmaddRR");
        assert!(fmadd.fmuladd_may_unfuse);

        let machine = selected.to_ir_func();
        let fmadd_id = machine
            .block(machine.entry)
            .insts
            .iter()
            .copied()
            .find(|&id| machine.inst(id).opcode == AArch64Opcode::FmaddRR)
            .expect("converted machine function must retain FmaddRR");
        assert!(
            machine
                .inst(fmadd_id)
                .flags
                .contains(trust_cg_ir::InstFlags::FMULADD_MAY_UNFUSE),
            "ISel-to-MachIR conversion must retain the source contract"
        );
    }

