    #[test]
    fn select_fcvt_from_int_i32_to_f32() {
        let sig = Signature {
            params: vec![Type::I32],
            returns: vec![Type::F32],
        };
        let mut isel = InstructionSelector::new("i2f".to_string(), sig.clone());
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::FcvtFromInt { src_ty: Type::I32 },
                args: vec![Value(0)],
                results: vec![Value(1)],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        // Signed i32->f32 must SIGN-extend (SXTW) before SCVTF: the encoder
        // emits SCVTF with sf=1 (64-bit X source), so a bare 32-bit source
        // would read negatives as huge positives. See
        // e2e_aarch64_sitofp_signext.rs (P0 miscompile fix 2026-07-04;
        // origin's owner #12 fix is identical). Position-independent asserts.
        let insts = &mfunc.blocks[&entry].insts;
        let sxtw = insts
            .iter()
            .position(|i| matches!(i.opcode, AArch64Opcode::Sxtw))
            .expect("i32->f32 sitofp must SIGN-extend (SXTW) before SCVTF");
        let scvtf = insts
            .iter()
            .position(|i| matches!(i.opcode, AArch64Opcode::ScvtfRR))
            .expect("i32->f32 sitofp must emit SCVTF");
        assert!(
            sxtw < scvtf,
            "SXTW must precede SCVTF (else negatives miscompile)"
        );
    }

