    #[test]
    fn select_fcvt_from_int_i64_to_seeded_f32_uses_f32_result() {
        let (mut isel, entry) = make_empty_isel();
        let src = Value(0);
        let result = Value(1);
        let src_vreg = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(src, ISelOperand::VReg(src_vreg), Type::I64);
        isel.value_types.insert(result, Type::F32);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::FcvtFromInt { src_ty: Type::I64 },
                args: vec![src],
                results: vec![result],
            },
            entry,
        )
        .unwrap();

        match isel.value_map.get(&result) {
            Some(ISelOperand::VReg(vreg)) => assert_eq!(vreg.class, RegClass::Fpr32),
            other => panic!("expected Fpr32 VReg result for fcvt i64->f32, got {other:?}"),
        }
        assert_eq!(isel.value_types.get(&result), Some(&Type::F32));

        let mfunc = isel.finalize();
        assert_eq!(mfunc.blocks[&entry].insts[0].opcode, AArch64Opcode::ScvtfRR);
    }

    #[test]
    fn select_fcvt_from_int_i16_to_f16_uses_fpr16() {
        let (mut isel, entry) = make_empty_isel();
        let src = Value(0);
        let result = Value(1);
        let src_vreg = isel.new_vreg(RegClass::Gpr32);
        isel.define_value(src, ISelOperand::VReg(src_vreg), Type::I16);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::FcvtFromInt { src_ty: Type::I16 },
                args: vec![src],
                results: vec![result],
            },
            entry,
        )
        .unwrap();

        match isel.value_map.get(&result) {
            Some(ISelOperand::VReg(vreg)) => assert_eq!(vreg.class, RegClass::Fpr16),
            other => panic!("expected VReg result for fcvt i16->f16, got {:?}", other),
        }
        assert_eq!(isel.value_types.get(&result), Some(&Type::F16));

        let mfunc = isel.finalize();
        // Signed i16->f16 must SIGN-extend (SXTH) before SCVTF (sf=1 X source);
        // otherwise negative i16 inputs miscompile. See
        // e2e_aarch64_sitofp_signext.rs (P0 fix 2026-07-04; origin's owner #12
        // fix is identical). Position-independent asserts.
        let insts = &mfunc.blocks[&entry].insts;
        let sxth = insts
            .iter()
            .position(|i| matches!(i.opcode, AArch64Opcode::Sxth))
            .expect("i16->f16 sitofp must SIGN-extend (SXTH) before SCVTF");
        let scvtf = insts
            .iter()
            .position(|i| matches!(i.opcode, AArch64Opcode::ScvtfRR))
            .expect("i16->f16 sitofp must emit SCVTF");
        assert!(
            sxth < scvtf,
            "SXTH must precede SCVTF (else negatives miscompile)"
        );
    }

    #[test]
    fn select_fcvt_to_int_f16_to_i16_uses_half_source_hint() {
        let (mut isel, entry) = make_empty_isel();
        let src = Value(0);
        let result = Value(1);
        let src_vreg = isel.new_vreg(RegClass::Fpr16);
        isel.define_value(src, ISelOperand::VReg(src_vreg), Type::F16);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::FcvtToInt { dst_ty: Type::I16 },
                args: vec![src],
                results: vec![result],
            },
            entry,
        )
        .unwrap();

        match isel.value_map.get(&result) {
            Some(ISelOperand::VReg(vreg)) => assert_eq!(vreg.class, RegClass::Gpr32),
            other => panic!(
                "expected Gpr32 VReg result for fcvt f16->i16, got {:?}",
                other
            ),
        }
        assert_eq!(isel.value_types.get(&result), Some(&Type::I16));

        let mfunc = isel.finalize();
        let inst = &mfunc.blocks[&entry].insts[0];
        assert_eq!(inst.opcode, AArch64Opcode::FcvtzsRR);
        assert_eq!(inst.operands[2], ISelOperand::Imm(16));
    }

