    #[test]
    fn select_tls_ref_tlv_indirect() {
        let (mut isel, entry) = make_empty_isel();
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::TlsRef {
                    name: "thread_local_var".to_string(),
                    model: TlsModel::Tlv,
                    local_exec_offset: None,
                },
                args: vec![],
                results: vec![Value(0)],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];
        // Full Darwin TLV access:
        //   [0] ADRP   dst, var@TLVPPAGE
        //   [1] LdrTlvp dst, [dst, var@TLVPPAGEOFF]   (dst = descriptor address)
        //   [2] LDR    thunk, [dst]                   (thunk = descriptor word 0)
        //   [3] Copy   x0, dst                        (pass descriptor to thunk)
        //   [4] BLR    thunk                          (returns var addr in x0)
        //   [5] Copy   dst, x0                        (result = var address)
        assert_eq!(mblock.insts.len(), 6);
        assert_eq!(mblock.insts[0].opcode, AArch64Opcode::Adrp);
        assert_eq!(
            mblock.insts[0].operands[1],
            ISelOperand::Symbol("thread_local_var".to_string())
        );
        assert_eq!(mblock.insts[1].opcode, AArch64Opcode::LdrTlvp);
        assert_eq!(
            mblock.insts[1].operands[2],
            ISelOperand::Symbol("thread_local_var".to_string())
        );
        // The descriptor's thunk is loaded from [descriptor + 0].
        assert_eq!(mblock.insts[2].opcode, AArch64Opcode::LdrRI);
        assert_eq!(mblock.insts[2].operands[2], ISelOperand::Imm(0));
        // The descriptor address is passed to the thunk in x0.
        assert_eq!(mblock.insts[3].opcode, AArch64Opcode::Copy);
        assert_eq!(mblock.insts[3].operands[0], ISelOperand::PReg(gpr::X0));
        // The thunk is called indirectly; x0 is an implicit use (the arg).
        assert_eq!(mblock.insts[4].opcode, AArch64Opcode::Blr);
        assert!(mblock.insts[4].implicit_uses.contains(&gpr::X0));
        // The returned variable address (x0) is copied into the result.
        assert_eq!(mblock.insts[5].opcode, AArch64Opcode::Copy);
        assert_eq!(mblock.insts[5].operands[1], ISelOperand::PReg(gpr::X0));
    }

    #[test]
    fn select_tls_ref_dynamic_models_fail_closed() {
        // GD/LD stay fail-closed by VERDICT (unreachable-by-lane): they exist
        // for dlopen'd-module TLS and trust-cg emits main-executable objects
        // only. InitialExec is no longer in this list — it lowers to the
        // GOT-indirect TPREL sequence (see the test below).
        for model in [TlsModel::GeneralDynamic, TlsModel::LocalDynamic] {
            let (mut isel, entry) = make_empty_isel();
            let err = isel
                .select_instruction(
                    &Instruction {
                        opcode: Opcode::TlsRef {
                            name: "thread_local_var".to_string(),
                            model,
                            local_exec_offset: None,
                        },
                        args: vec![],
                        results: vec![Value(0)],
                    },
                    entry,
                )
                .expect_err("GD/LD TLS models must not lower");

            assert!(
                matches!(
                    err,
                    ISelError::UnsupportedTlsRefModel {
                        model: rejected,
                        reason
                    } if rejected == model
                        && reason.contains("unreachable-by-lane")
                ),
                "unexpected error for {model:?}: {err}"
            );
        }
    }

    /// ELF initial-exec `#[thread_local]` read: the canonical gcc/binutils
    /// GOT-indirect TPREL sequence. The ADRP/LdrGottprel pair carries the
    /// symbol for encode-time TLSIE relocation pairing
    /// (`R_AARCH64_TLSIE_ADR_GOTTPREL_PAGE21` / `_LD64_GOTTPREL_LO12_NC`).
    #[test]
    fn select_tls_ref_initial_exec_emits_got_indirect_tprel_sequence() {
        let (mut isel, entry) = make_empty_isel();
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::TlsRef {
                    name: "tls_ie_var".to_string(),
                    model: TlsModel::InitialExec,
                    local_exec_offset: None,
                },
                args: vec![],
                results: vec![Value(0)],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];
        //   [0] ADRP        got, :gottprel:sym
        //   [1] LdrGottprel got, [got, #:gottprel_lo12:sym]  (got = TPREL(sym))
        //   [2] MRS         tp, TPIDR_EL0
        //   [3] ADD         dst, tp, got                     (dst = TP + TPREL)
        assert_eq!(mblock.insts.len(), 4);
        assert_eq!(mblock.insts[0].opcode, AArch64Opcode::Adrp);
        assert_eq!(
            mblock.insts[0].operands[1],
            ISelOperand::Symbol("tls_ie_var".to_string())
        );
        assert_eq!(mblock.insts[1].opcode, AArch64Opcode::LdrGottprel);
        // The LDR's base register is the ADRP's destination (same-vreg
        // pairing, required by the encode-time TLSIE pairing scan).
        assert_eq!(mblock.insts[1].operands[1], mblock.insts[0].operands[0]);
        assert_eq!(
            mblock.insts[1].operands[2],
            ISelOperand::Symbol("tls_ie_var".to_string())
        );
        assert_eq!(mblock.insts[2].opcode, AArch64Opcode::Mrs);
        assert_eq!(
            mblock.insts[2].operands[1],
            ISelOperand::Imm(TPIDR_EL0_SYSREG)
        );
        assert_eq!(mblock.insts[3].opcode, AArch64Opcode::AddRR);
        // ADD dst, tp, got — reads the MRS result and the loaded TPREL.
        assert_eq!(mblock.insts[3].operands[1], mblock.insts[2].operands[0]);
        assert_eq!(mblock.insts[3].operands[2], mblock.insts[1].operands[0]);
    }

