    /// `LocalExec` WITHOUT a pre-resolved offset is the AOT ELF form: the
    /// TPREL offset is the static linker's job, so selection must emit the
    /// canonical symbolic sequence `MRS; ADD tprel_hi12(sym); ADD
    /// tprel_lo12_nc(sym)` (both ADDs unconditionally, imm patched via
    /// `R_AARCH64_TLSLE_ADD_TPREL_HI12`/`_LO12_NC`) rather than error.
    #[test]
    fn test_select_tls_ref_local_exec_no_offset_emits_symbolic_tprel_sequence() {
        let (mut isel, entry) = make_empty_isel();
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::TlsRef {
                    name: "thread_local_var".to_string(),
                    model: TlsModel::LocalExec,
                    local_exec_offset: None,
                },
                args: vec![],
                results: vec![Value(0)],
            },
            entry,
        )
        .expect("AOT ELF local-exec TlsRef must select");

        let mblock = &isel.func.blocks[&entry];
        assert_eq!(mblock.insts.len(), 3);
        assert_eq!(mblock.insts[0].opcode, AArch64Opcode::Mrs);
        assert_eq!(
            mblock.insts[0].operands[1],
            ISelOperand::Imm(TPIDR_EL0_SYSREG)
        );
        assert_eq!(mblock.insts[1].opcode, AArch64Opcode::AddTprelHi12);
        assert_eq!(
            mblock.insts[1].operands[2],
            ISelOperand::Symbol("thread_local_var".to_string())
        );
        assert_eq!(mblock.insts[2].opcode, AArch64Opcode::AddTprelLo12);
        assert_eq!(
            mblock.insts[2].operands[2],
            ISelOperand::Symbol("thread_local_var".to_string())
        );
        // The result must be defined (usable by later blocks/instructions).
        assert!(isel.value_map.contains_key(&Value(0)));
    }

