    #[test]
    fn to_ir_func_preserves_runtime_stack_slot_metadata() {
        let (mut isel, _entry) = make_empty_isel();
        isel.set_stack_slots(vec![
            StackSlotInfo::new(8, 8),
            StackSlotInfo::new_dynamic(StackSlotSizeSource::Value(42), 16),
        ]);

        let ir_func = isel.finalize().to_ir_func();

        assert_eq!(ir_func.stack_slots.len(), 2);
        assert_eq!(
            ir_func.stack_slots[0].allocation,
            StackSlotAllocationKind::Fixed
        );
        assert_eq!(
            ir_func.stack_slots[1].allocation,
            StackSlotAllocationKind::RuntimeSized {
                size_source: StackSlotSizeSource::Value(42)
            }
        );
        assert_eq!(ir_func.stack_slots[1].size, 0);
        assert_eq!(ir_func.stack_slots[1].align, 16);
    }

