    #[test]
    fn select_call_emits_symbol_operand() {
        // Test that Call { name } from the adapter produces a BL with Symbol operand.
        let (mut isel, entry) = make_empty_isel();

        // Define an arg value (simulating a function parameter).
        let vreg = isel.new_vreg(RegClass::Gpr32);
        isel.define_value(Value(0), ISelOperand::VReg(vreg), Type::I32);

        // Select a Call instruction.
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Call {
                    name: "my_callee".to_string(),
                },
                args: vec![Value(0)],
                results: vec![Value(1)],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];

        // Should contain at least: MOV (arg to X0) + BL + MOV (X0 to result)
        // Find the BL instruction and verify it has a Symbol operand.
        let bl_inst = mblock.insts.iter().find(|i| i.opcode == AArch64Opcode::Bl);
        assert!(
            bl_inst.is_some(),
            "Expected BL instruction for function call"
        );
        let bl = bl_inst.unwrap();
        assert_eq!(
            bl.operands[0],
            ISelOperand::Symbol("my_callee".to_string()),
            "BL should have Symbol operand with callee name"
        );
    }

    #[test]
    fn select_return_i32_to_abi_x0_zero_extends() {
        let sig = Signature {
            params: vec![],
            returns: vec![Type::I32],
        };
        let mut isel = InstructionSelector::new("ret_i32".to_string(), sig);
        let entry = Block(0);
        isel.func.ensure_block(entry);

        let vreg = isel.new_vreg(RegClass::Gpr32);
        isel.define_value(Value(0), ISelOperand::VReg(vreg), Type::I32);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Return,
                args: vec![Value(0)],
                results: vec![],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        assert_eq!(insts[0].opcode, AArch64Opcode::Uxtw);
        assert_eq!(insts[0].operands[0], ISelOperand::PReg(gpr::X0));
        assert!(
            matches!(insts[0].operands[1], ISelOperand::VReg(v) if v.class == RegClass::Gpr32),
            "i32 ABI return must zero-extend the Gpr32 source into X0"
        );
        assert_eq!(insts[1].opcode, AArch64Opcode::Ret);
    }

    #[test]
    fn select_call_i32_arg_to_abi_x0_zero_extends() {
        let (mut isel, entry) = make_empty_isel();

        let vreg = isel.new_vreg(RegClass::Gpr32);
        isel.define_value(Value(0), ISelOperand::VReg(vreg), Type::I32);

        isel.select_call("takes_i32", &[Value(0)], &[], &[], entry)
            .unwrap();

        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];
        // A 32-bit arg is marshaled as a genuine 32-bit `Copy` to the W alias
        // of the X arg register (`mov w0, wv` — a W write zero-extends X0),
        // NOT an opaque `Uxtw X0 <- v`: the Copy form is what the allocator's
        // copy-hint/identity machinery can coalesce away in call loops. The
        // encoded bytes are identical when the copy survives.
        assert_eq!(mblock.insts[0].opcode, AArch64Opcode::Copy);
        assert_eq!(
            mblock.insts[0].operands[0],
            ISelOperand::PReg(trust_cg_ir::aarch64_regs::W0)
        );
        assert!(
            matches!(mblock.insts[0].operands[1], ISelOperand::VReg(v) if v.class == RegClass::Gpr32),
            "i32 ABI argument must be a 32-bit copy into W0 (zero-extends X0)"
        );
        assert!(mblock.insts[0].is_call_arg_setup);
        assert_eq!(mblock.insts[1].opcode, AArch64Opcode::Bl);
    }

