    #[test]
    fn select_call_records_abi_arg_implicit_uses() {
        let (mut isel, entry) = make_empty_isel();

        let i64_arg = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(0), ISelOperand::VReg(i64_arg), Type::I64);

        let f64_arg = isel.new_vreg(RegClass::Fpr64);
        isel.define_value(Value(1), ISelOperand::VReg(f64_arg), Type::F64);

        let i128_lo = isel.new_vreg(RegClass::Gpr64);
        let i128_hi = isel.new_vreg(RegClass::Gpr64);
        isel.define_i128_value(Value(2), i128_lo, i128_hi);

        let medium_ty = Type::Struct(vec![Type::I64, Type::I64]);
        let medium_ptr = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(3), ISelOperand::VReg(medium_ptr), medium_ty);

        let large_ty = Type::Struct(vec![Type::I64, Type::I64, Type::I64]);
        let large_ptr = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(4), ISelOperand::VReg(large_ptr), large_ty);

        let hfa_ty = Type::Struct(vec![Type::F32, Type::F32]);
        let hfa_ptr = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(5), ISelOperand::VReg(hfa_ptr), hfa_ty);

        isel.select_call(
            "takes_mixed_args",
            &[Value(0), Value(1), Value(2), Value(3), Value(4), Value(5)],
            &[],
            &[],
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];
        let bl = mblock
            .insts
            .iter()
            .find(|inst| inst.opcode == AArch64Opcode::Bl)
            .expect("direct call should emit BL");

        let expected = [
            gpr::X0, // i64
            gpr::D0, // f64
            gpr::X1, // i128 lo
            gpr::X2, // i128 hi
            gpr::X3, // 16-byte aggregate low register
            gpr::X4, // 16-byte aggregate high register
            gpr::X5, // large aggregate pointer
            gpr::S1, // HFA field 0; F64 consumed FPR slot 0
            gpr::S2, // HFA field 1
        ];
        for preg in expected {
            assert!(
                bl.implicit_uses.contains(&preg),
                "BL missing ABI implicit use {preg:?}"
            );
        }
        for preg in [gpr::X0, gpr::X16, gpr::V0] {
            assert!(
                bl.implicit_defs.contains(&preg),
                "BL missing ABI implicit def {preg:?}"
            );
        }

        let isel_setup_count = mblock
            .insts
            .iter()
            .filter(|inst| inst.is_call_arg_setup)
            .count();
        assert_eq!(
            isel_setup_count, 9,
            "every scalar, pair, aggregate, indirect, and HFA ABI register setup must carry provenance"
        );

        let ir_func = mfunc.to_ir_func();
        let ir_bl = ir_func
            .insts
            .iter()
            .find(|inst| inst.opcode == AArch64Opcode::Bl)
            .expect("IR should preserve BL");
        for preg in expected {
            assert!(
                ir_bl.implicit_uses.contains(&preg),
                "IR BL missing ABI implicit use {preg:?}"
            );
        }
        for preg in [gpr::X0, gpr::X16, gpr::V0] {
            assert!(
                ir_bl.implicit_defs.contains(&preg),
                "IR BL missing ABI implicit def {preg:?}"
            );
        }
        assert_eq!(
            ir_func
                .insts
                .iter()
                .filter(|inst| inst.flags.is_call_arg_setup())
                .count(),
            isel_setup_count,
            "ISel-to-MachIR conversion must preserve every setup marker"
        );
    }

    #[test]
    fn select_call_indirect_records_abi_arg_implicit_uses() {
        let (mut isel, entry) = make_empty_isel();

        let fn_ptr = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(0), ISelOperand::VReg(fn_ptr), Type::I64);

        let i32_arg = isel.new_vreg(RegClass::Gpr32);
        isel.define_value(Value(1), ISelOperand::VReg(i32_arg), Type::I32);

        let f32_arg = isel.new_vreg(RegClass::Fpr32);
        isel.define_value(Value(2), ISelOperand::VReg(f32_arg), Type::F32);

        let large_ty = Type::Struct(vec![Type::I64, Type::I64, Type::I64]);
        let large_ptr = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(3), ISelOperand::VReg(large_ptr), large_ty);

        isel.select_call_indirect(&Value(0), &[Value(1), Value(2), Value(3)], &[], &[], entry)
            .unwrap();

        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];
        let blr = mblock
            .insts
            .iter()
            .find(|inst| inst.opcode == AArch64Opcode::Blr)
            .expect("indirect call should emit BLR");

        assert_eq!(blr.operands, vec![ISelOperand::VReg(fn_ptr)]);
        // F32 arg -> typed S0 (S_ARG_REGS[0]) in implicit_uses (not the
        // canonical V0); the V128/clobber paths still use V0 in implicit_defs.
        for preg in [gpr::X0, gpr::S0, gpr::X1] {
            assert!(
                blr.implicit_uses.contains(&preg),
                "BLR missing ABI implicit use {preg:?}"
            );
        }
        for preg in [gpr::X0, gpr::X16, gpr::V0] {
            assert!(
                blr.implicit_defs.contains(&preg),
                "BLR missing ABI implicit def {preg:?}"
            );
        }

        let ir_func = mfunc.to_ir_func();
        let ir_blr = ir_func
            .insts
            .iter()
            .find(|inst| inst.opcode == AArch64Opcode::Blr)
            .expect("IR should preserve BLR");
        assert_eq!(
            ir_blr.operands,
            vec![trust_cg_ir::MachOperand::VReg(fn_ptr)]
        );
        // F32 arg -> typed S0 (S_ARG_REGS[0]) in implicit_uses (not the
        // canonical V0); the V128/clobber paths still use V0 in implicit_defs.
        for preg in [gpr::X0, gpr::S0, gpr::X1] {
            assert!(
                ir_blr.implicit_uses.contains(&preg),
                "IR BLR missing ABI implicit use {preg:?}"
            );
        }
        for preg in [gpr::X0, gpr::X16, gpr::V0] {
            assert!(
                ir_blr.implicit_defs.contains(&preg),
                "IR BLR missing ABI implicit def {preg:?}"
            );
        }
    }

    // =======================================================================
    // CondCode operand preserved through Brif (issue #69)
    // =======================================================================

    #[test]
    fn select_brif_emits_condcode_operand() {
        // Test that Brif from the adapter produces B.cond with CondCode operand.
        let (mut isel, entry) = make_empty_isel();

        // Define a boolean condition value.
        let vreg = isel.new_vreg(RegClass::Gpr32);
        isel.define_value(Value(0), ISelOperand::VReg(vreg), Type::B1);

        let then_block = Block(1);
        let else_block = Block(2);
        isel.func.ensure_block(then_block);
        isel.func.ensure_block(else_block);

        // Select a Brif instruction.
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Brif {
                    cond: Value(0),
                    then_dest: then_block,
                    else_dest: else_block,
                },
                args: vec![Value(0)],
                results: vec![],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];

        // Expected: CMP W, #0 + B.NE then + B else
        assert!(mblock.insts.len() >= 3, "Brif should emit CMP + B.cond + B");

        // Find B.cond and verify CondCode operand.
        let bcc_inst = mblock
            .insts
            .iter()
            .find(|i| i.opcode == AArch64Opcode::BCond);
        assert!(bcc_inst.is_some(), "Expected B.cond instruction");
        let bcc = bcc_inst.unwrap();
        assert_eq!(
            bcc.operands[0],
            ISelOperand::CondCode(AArch64CC::NE),
            "B.cond should have NE condition code (branch if nonzero)"
        );
        assert_eq!(
            bcc.operands[1],
            ISelOperand::Block(then_block),
            "B.cond should target the then block"
        );
    }

