    /// Shape pin for the W32 SMULL magic path on ReedSolomon's `x % 255`: the
    /// exact clang-parity sequence SMULL; LSR #32; ADD; ASR #7; LSR #31; ADD;
    /// then the Mersenne remainder tail `q - (q<<8)` + ADD (no SDIV/MSUB, no
    /// SXTW widen). Semantics are proven by `magic_udiv`'s exhaustive-probe
    /// sims + the GM band check; this test pins the EMITTED recipe so a
    /// regression back to the 64-bit path (or to hardware SDIV) is caught.
    #[test]
    fn select_srem_i32_by_255_emits_smull_magic_sequence() {
        let (mut isel, entry) = make_add_isel();
        let instructions = vec![
            Instruction {
                opcode: Opcode::Iconst {
                    ty: Type::I32,
                    imm: 255,
                },
                args: vec![],
                results: vec![Value(2)],
            },
            Instruction {
                opcode: Opcode::Srem,
                args: vec![Value(0), Value(2)],
                results: vec![Value(3)],
            },
        ];
        isel.seed_iconst_origins([instructions.as_slice()]);
        isel.select_block(entry, &instructions).unwrap();
        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];
        let opcodes: Vec<AArch64Opcode> = mblock.insts.iter().map(|i| i.opcode).collect();
        assert!(
            !opcodes.contains(&AArch64Opcode::SDiv),
            "srem-by-255 must not fall back to hardware SDIV: {opcodes:?}"
        );
        assert!(
            !opcodes.contains(&AArch64Opcode::Sxtw),
            "the SMULL path folds the widen; no SXTW expected: {opcodes:?}"
        );
        // The tail of the block is the exact magic + Mersenne-remainder recipe.
        let tail: Vec<AArch64Opcode> = opcodes[opcodes.len() - 8..].to_vec();
        assert_eq!(
            tail,
            vec![
                AArch64Opcode::Smull,
                AArch64Opcode::LsrRI,      // #32: mulhi
                AArch64Opcode::AddRR,      // + x (d > 0, magic < 0)
                AArch64Opcode::AsrRI,      // #7
                AArch64Opcode::LsrRI,      // #31: sign bit
                AArch64Opcode::AddRR,      // round toward zero
                AArch64Opcode::SubRRShift, // q - (q << 8) = -q*255
                AArch64Opcode::AddRR,      // x + (-q*255)
            ],
            "srem-by-255 recipe drifted"
        );
    }

    #[test]
    fn select_srem_i64() {
        let (mut isel, entry) = make_i64_isel();
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Srem,
                args: vec![Value(0), Value(1)],
                results: vec![Value(2)],
            },
            entry,
        )
        .unwrap();
        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];
        assert_eq!(mblock.insts.len(), 4);
        assert_eq!(mblock.insts[2].opcode, AArch64Opcode::SDiv);
        assert_eq!(mblock.insts[3].opcode, AArch64Opcode::Msub);
    }

    #[test]
    fn select_srem_msub_operand_order() {
        // Verify MSUB operand order: MSUB dst, tmp(quotient), divisor, dividend
        // This ensures result = dividend - quotient * divisor
        let (mut isel, entry) = make_add_isel();
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Srem,
                args: vec![Value(0), Value(1)],
                results: vec![Value(2)],
            },
            entry,
        )
        .unwrap();
        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];

        let div_inst = &mblock.insts[2];
        let msub_inst = &mblock.insts[3];

        // SDIV dst=tmp, lhs=dividend, rhs=divisor
        assert_eq!(div_inst.opcode, AArch64Opcode::SDiv);
        let div_dst = &div_inst.operands[0]; // tmp vreg
        let dividend_op = &div_inst.operands[1]; // dividend
        let divisor_op = &div_inst.operands[2]; // divisor

        // MSUB dst, Rn=tmp, Rm=divisor, Ra=dividend
        assert_eq!(msub_inst.opcode, AArch64Opcode::Msub);
        assert_eq!(
            &msub_inst.operands[1], div_dst,
            "MSUB Rn should be quotient from SDIV"
        );
        assert_eq!(
            &msub_inst.operands[2], divisor_op,
            "MSUB Rm should be divisor"
        );
        assert_eq!(
            &msub_inst.operands[3], dividend_op,
            "MSUB Ra should be dividend"
        );
    }

