    #[test]
    fn select_ctpop_i64_uses_swar_sequence() {
        let (mut isel, entry) = make_empty_isel();
        let src = Value(0);
        let result = Value(1);
        let src_vreg = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(src, ISelOperand::VReg(src_vreg), Type::I64);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::CtPop,
                args: vec![src],
                results: vec![result],
            },
            entry,
        )
        .unwrap();

        assert_eq!(isel.value_types.get(&result), Some(&Type::I64));
        match isel.value_map.get(&result) {
            Some(ISelOperand::VReg(vreg)) => assert_eq!(vreg.class, RegClass::Gpr64),
            other => panic!("expected Gpr64 result for ctpop i64, got {:?}", other),
        }

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        assert_eq!(
            insts.first().map(|inst| inst.opcode),
            Some(AArch64Opcode::LsrRI)
        );
        assert_eq!(
            insts.last().map(|inst| inst.opcode),
            Some(AArch64Opcode::AndRI)
        );
        assert!(insts.iter().any(|inst| inst.opcode == AArch64Opcode::SubRR));
        assert!(insts.iter().any(|inst| inst.opcode == AArch64Opcode::AddRR));
        assert!(insts.iter().any(|inst| inst.opcode == AArch64Opcode::AndRI));
    }

