    /// Regression: the i8 ctpop SWAR sequence used to mask its constants down to
    /// the operand width, emitting `AND Wd, Wn, #0x55` (and 0x33, 0x0f0f-style
    /// narrowed values) which are NOT valid AArch64 32-bit logical immediates,
    /// so the encoder aborted. Every `AndRI` immediate emitted for a narrow
    /// ctpop must be encodable as a 32-bit logical immediate.
    #[test]
    fn select_ctpop_i8_emits_only_encodable_logical_imms() {
        // Standalone AArch64 32-bit logical-immediate encodability check
        // (matches the codegen encoder's contract without depending on it).
        fn is_encodable_logical_imm32(value: u64) -> bool {
            const DATASIZE: u32 = 32;
            let value = value & 0xffff_ffff;
            if value == 0 || value == 0xffff_ffff {
                return false;
            }
            let mut esize = 2u32;
            while esize <= DATASIZE {
                if DATASIZE.is_multiple_of(esize) {
                    let elem = value & ((1u64 << esize) - 1);
                    let mut replicated = true;
                    let mut v = value;
                    for _ in 0..(DATASIZE / esize) {
                        if v & ((1u64 << esize) - 1) != elem {
                            replicated = false;
                            break;
                        }
                        v >>= esize;
                    }
                    if replicated {
                        // Within the element, some rotation must be a contiguous
                        // run of ones (`(1<<k)-1`, with 1 <= k < esize).
                        let mask = (1u64 << esize) - 1;
                        for r in 0..esize {
                            let rot = ((elem >> r) | (elem << (esize - r))) & mask;
                            if rot != 0 && rot != mask && (rot & (rot + 1)) == 0 {
                                return true;
                            }
                        }
                        return false;
                    }
                }
                esize <<= 1;
            }
            false
        }

        let (mut isel, entry) = make_empty_isel();
        let src = Value(0);
        let result = Value(1);
        // i8 ctpop lowers into Gpr32 (see reg_class_for_type).
        let src_vreg = isel.new_vreg(RegClass::Gpr32);
        isel.define_value(src, ISelOperand::VReg(src_vreg), Type::I8);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::CtPop,
                args: vec![src],
                results: vec![result],
            },
            entry,
        )
        .unwrap();

        assert_eq!(isel.value_types.get(&result), Some(&Type::I8));
        let mfunc = isel.finalize();
        let mut saw_and = false;
        for inst in &mfunc.blocks[&entry].insts {
            if inst.opcode == AArch64Opcode::AndRI {
                saw_and = true;
                let ISelOperand::Imm(imm) = inst.operands[2] else {
                    panic!(
                        "AndRI immediate operand must be an Imm, got {:?}",
                        inst.operands[2]
                    );
                };
                assert!(
                    is_encodable_logical_imm32(imm as u64),
                    "i8 ctpop emitted non-encodable AND immediate {:#x}",
                    imm as u64,
                );
            }
        }
        assert!(
            saw_and,
            "expected the i8 ctpop SWAR sequence to emit AndRI masks"
        );
    }

    #[test]
    fn select_ctpop_i128_sums_both_halves() {
        let (mut isel, entry) = make_empty_isel();
        // An i128 source needs BOTH halves bound (register pair).
        let src = Value(0);
        let lo = isel.new_vreg(RegClass::Gpr64);
        let hi = isel.new_vreg(RegClass::Gpr64);
        isel.define_i128_value(src, lo, hi);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::CtPop,
                args: vec![src],
                results: vec![Value(1)],
            },
            entry,
        )
        .expect("i128 ctpop should lower (popcount of each half, summed)");

        // The result is a bound i128 register pair (low = count, high = 0).
        assert_eq!(isel.value_type(&Value(1)), Type::I128);
        assert!(
            isel.i128_high_map.contains_key(&Value(1)),
            "i128 ctpop result must bind its high half"
        );

        // The two per-half SWARs are summed with an AddRR, and the high half is
        // materialized to zero with a MOVZ.
        let ops: Vec<_> = isel.func.blocks[&entry]
            .insts
            .iter()
            .map(|i| i.opcode)
            .collect();
        assert!(
            ops.contains(&AArch64Opcode::AddRR),
            "expected an AddRR summing the two half popcounts, got {ops:?}"
        );
        assert!(
            ops.contains(&AArch64Opcode::Movz),
            "expected a MOVZ zeroing the high half, got {ops:?}"
        );
    }

    #[test]
    fn select_i128_atomics_fail_closed() {
        // 128-bit single-copy atomicity (LDXP/STXP/CASP) is not lowered, for the
        // I128 register-pair OR the V128 vector form. Each must fail CLOSED —
        // silently emitting a 64-bit atomic op over the low half (and, for V128,
        // from the wrong register file) would be a wrong-atomic-semantics
        // miscompile. (The guards return before any operand is read, so
        // undefined placeholder operands are fine.)
        for ty in [Type::I128, Type::V128] {
            {
                let (mut isel, entry) = make_empty_isel();
                let err = isel
                    .select_instruction(
                        &Instruction {
                            opcode: Opcode::AtomicLoad {
                                ty: ty.clone(),
                                ordering: AtomicOrdering::SeqCst,
                            },
                            args: vec![Value(0)],
                            results: vec![Value(1)],
                        },
                        entry,
                    )
                    .unwrap_err();
                assert!(
                    matches!(err, ISelError::UnsupportedOpcode(_)),
                    "{ty:?} AtomicLoad must fail closed, got {err:?}"
                );
            }
            {
                let (mut isel, entry) = make_empty_isel();
                let err = isel
                    .select_instruction(
                        &Instruction {
                            opcode: Opcode::AtomicStore {
                                ty: ty.clone(),
                                ordering: AtomicOrdering::SeqCst,
                            },
                            args: vec![Value(0), Value(1)],
                            results: vec![],
                        },
                        entry,
                    )
                    .unwrap_err();
                assert!(
                    matches!(err, ISelError::UnsupportedOpcode(_)),
                    "{ty:?} AtomicStore must fail closed, got {err:?}"
                );
            }
            {
                let (mut isel, entry) = make_empty_isel();
                let err = isel
                    .select_instruction(
                        &Instruction {
                            opcode: Opcode::CmpXchg {
                                ty: ty.clone(),
                                success: AtomicOrdering::SeqCst,
                                failure: AtomicOrdering::SeqCst,
                            },
                            args: vec![Value(0), Value(1), Value(2)],
                            results: vec![Value(3)],
                        },
                        entry,
                    )
                    .unwrap_err();
                assert!(
                    matches!(err, ISelError::UnsupportedCmpXchg { .. }),
                    "{ty:?} CmpXchg must fail closed, got {err:?}"
                );
            }
        }
    }

    fn fresh_value(next: &mut u32) -> Value {
        let value = Value(*next);
        *next += 1;
        value
    }

    fn push_bitreverse_iconst(
        instrs: &mut Vec<Instruction>,
        next: &mut u32,
        ty: &Type,
        imm: i64,
    ) -> Value {
        let value = fresh_value(next);
        instrs.push(Instruction {
            opcode: Opcode::Iconst {
                ty: ty.clone(),
                imm,
            },
            args: vec![],
            results: vec![value],
        });
        value
    }

    fn bitreverse_ladder(ty: Type, src: Value, dst: Value) -> (Vec<Instruction>, Value) {
        let (steps, final_shift) = InstructionSelector::bitreverse_spec(&ty).unwrap();
        let mut instrs = Vec::new();
        let mut next = 100;
        let mut current = src;
        let mut first_combined = None;

        for &(shift, mask) in steps {
            let shift_val = push_bitreverse_iconst(&mut instrs, &mut next, &ty, i64::from(shift));
            let mask_val = push_bitreverse_iconst(&mut instrs, &mut next, &ty, mask);
            let right = fresh_value(&mut next);
            instrs.push(Instruction {
                opcode: Opcode::Ushr,
                args: vec![current, shift_val],
                results: vec![right],
            });
            let right_masked = fresh_value(&mut next);
            instrs.push(Instruction {
                opcode: Opcode::Band,
                args: vec![right, mask_val],
                results: vec![right_masked],
            });
            let left_masked = fresh_value(&mut next);
            instrs.push(Instruction {
                opcode: Opcode::Band,
                args: vec![current, mask_val],
                results: vec![left_masked],
            });
            let left = fresh_value(&mut next);
            instrs.push(Instruction {
                opcode: Opcode::Ishl,
                args: vec![left_masked, shift_val],
                results: vec![left],
            });
            let combined = fresh_value(&mut next);
            instrs.push(Instruction {
                opcode: Opcode::Bor,
                args: vec![right_masked, left],
                results: vec![combined],
            });
            first_combined.get_or_insert(combined);
            current = combined;
        }

        let final_shift_val =
            push_bitreverse_iconst(&mut instrs, &mut next, &ty, i64::from(final_shift));
        let right = fresh_value(&mut next);
        instrs.push(Instruction {
            opcode: Opcode::Ushr,
            args: vec![current, final_shift_val],
            results: vec![right],
        });
        let left = fresh_value(&mut next);
        instrs.push(Instruction {
            opcode: Opcode::Ishl,
            args: vec![current, final_shift_val],
            results: vec![left],
        });
        instrs.push(Instruction {
            opcode: Opcode::Bor,
            args: vec![right, left],
            results: vec![dst],
        });

        (instrs, first_combined.unwrap())
    }

    fn bitreverse_signed_imm(ty: &Type, bits: u64) -> i64 {
        match ty {
            Type::I32 => (bits as u32 as i32) as i64,
            Type::I64 => bits as i64,
            other => panic!("unsupported bitreverse test type: {other:?}"),
        }
    }

    fn push_bitreverse_stack_load(
        instrs: &mut Vec<Instruction>,
        next: &mut u32,
        ty: &Type,
        ptr: Value,
    ) -> Value {
        let load = fresh_value(next);
        instrs.push(Instruction {
            opcode: Opcode::Load {
                ty: ty.clone(),
                align: None,
            },
            args: vec![ptr],
            results: vec![load],
        });
        load
    }

    fn bitreverse_stack_byte_swap_ladder(ty: Type, src: Value, dst: Value) -> Vec<Instruction> {
        let (steps, _) = InstructionSelector::bitreverse_spec(&ty).unwrap();
        let mut instrs = Vec::new();
        let mut next = 100;
        let ptr = fresh_value(&mut next);
        instrs.push(Instruction {
            opcode: Opcode::StackAddr { slot: 0 },
            args: vec![],
            results: vec![ptr],
        });
        instrs.push(Instruction {
            opcode: Opcode::Store {
                ty: ty.clone(),
                align: None,
            },
            args: vec![src, ptr],
            results: vec![],
        });

        for &(shift, mask) in &steps[..3] {
            let shift_val = push_bitreverse_iconst(&mut instrs, &mut next, &ty, i64::from(shift));
            let mask_val = push_bitreverse_iconst(&mut instrs, &mut next, &ty, mask);
            let right_load = push_bitreverse_stack_load(&mut instrs, &mut next, &ty, ptr);
            let right = fresh_value(&mut next);
            instrs.push(Instruction {
                opcode: Opcode::Ushr,
                args: vec![right_load, shift_val],
                results: vec![right],
            });
            let right_masked = fresh_value(&mut next);
            instrs.push(Instruction {
                opcode: Opcode::Band,
                args: vec![right, mask_val],
                results: vec![right_masked],
            });
            let left_load = push_bitreverse_stack_load(&mut instrs, &mut next, &ty, ptr);
            let left_masked = fresh_value(&mut next);
            instrs.push(Instruction {
                opcode: Opcode::Band,
                args: vec![left_load, mask_val],
                results: vec![left_masked],
            });
            let left = fresh_value(&mut next);
            instrs.push(Instruction {
                opcode: Opcode::Ishl,
                args: vec![left_masked, shift_val],
                results: vec![left],
            });
            let combined = fresh_value(&mut next);
            instrs.push(Instruction {
                opcode: Opcode::Bor,
                args: vec![right_masked, left],
                results: vec![combined],
            });
            instrs.push(Instruction {
                opcode: Opcode::Store {
                    ty: ty.clone(),
                    align: None,
                },
                args: vec![combined, ptr],
                results: vec![],
            });
        }

        let mut byte_terms = Vec::new();
        let terms = InstructionSelector::bitreverse_byte_swap_terms(&ty).unwrap();
        for (mask_bits, shift_left, shift) in terms.into_iter().rev() {
            let load = push_bitreverse_stack_load(&mut instrs, &mut next, &ty, ptr);
            let mask_val = push_bitreverse_iconst(
                &mut instrs,
                &mut next,
                &ty,
                bitreverse_signed_imm(&ty, mask_bits),
            );
            let masked = fresh_value(&mut next);
            instrs.push(Instruction {
                opcode: Opcode::Band,
                args: vec![load, mask_val],
                results: vec![masked],
            });
            let shift_val = push_bitreverse_iconst(&mut instrs, &mut next, &ty, i64::from(shift));
            let shifted = fresh_value(&mut next);
            instrs.push(Instruction {
                opcode: if shift_left {
                    Opcode::Ishl
                } else {
                    Opcode::Ushr
                },
                args: vec![masked, shift_val],
                results: vec![shifted],
            });
            byte_terms.push(shifted);
        }

        let mut acc = byte_terms[0];
        for (idx, term) in byte_terms.iter().copied().enumerate().skip(1) {
            let result = if idx == byte_terms.len() - 1 {
                dst
            } else {
                fresh_value(&mut next)
            };
            instrs.push(Instruction {
                opcode: Opcode::Bor,
                args: vec![acc, term],
                results: vec![result],
            });
            acc = result;
        }

        instrs
    }

    #[test]
    fn select_bitreverse_i32_ladder_emits_rbit() {
        let sig = Signature {
            params: vec![Type::I32],
            returns: vec![Type::I32],
        };
        let mut isel = InstructionSelector::new("bitrev32".to_string(), sig.clone());
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();

        let (instrs, _) = bitreverse_ladder(Type::I32, Value(0), Value(1));
        isel.select_block(entry, &instrs).unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        let rbits: Vec<_> = insts
            .iter()
            .filter(|inst| inst.opcode == AArch64Opcode::Rbit)
            .collect();
        assert_eq!(rbits.len(), 1, "expected one RBIT, got {insts:?}");
        assert!(
            !insts.iter().any(|inst| matches!(
                inst.opcode,
                AArch64Opcode::LsrRI
                    | AArch64Opcode::LslRI
                    | AArch64Opcode::AndRI
                    | AArch64Opcode::OrrRR
            )),
            "bitreverse ladder should be skipped after RBIT selection: {insts:?}"
        );
        match rbits[0].operands[0] {
            ISelOperand::VReg(vreg) => assert_eq!(vreg.class, RegClass::Gpr32),
            ref other => panic!("expected Gpr32 RBIT destination, got {other:?}"),
        }
    }

    #[test]
    fn select_bitreverse_i64_ladder_emits_rbit() {
        let sig = Signature {
            params: vec![Type::I64],
            returns: vec![Type::I64],
        };
        let mut isel = InstructionSelector::new("bitrev64".to_string(), sig.clone());
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();

        let (instrs, _) = bitreverse_ladder(Type::I64, Value(0), Value(1));
        isel.select_block(entry, &instrs).unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        let rbit = insts
            .iter()
            .find(|inst| inst.opcode == AArch64Opcode::Rbit)
            .expect("expected RBIT for i64 bitreverse ladder");
        match rbit.operands[0] {
            ISelOperand::VReg(vreg) => assert_eq!(vreg.class, RegClass::Gpr64),
            ref other => panic!("expected Gpr64 RBIT destination, got {other:?}"),
        }
    }

    #[test]
    fn select_bitreverse_i32_stack_byte_swap_ladder_emits_rbit() {
        let sig = Signature {
            params: vec![Type::I32],
            returns: vec![Type::I32],
        };
        let mut isel = InstructionSelector::new("bitrev32_stack".to_string(), sig.clone());
        let entry = Block(0);
        isel.lower_formal_arguments(&sig, entry).unwrap();

        let instrs = bitreverse_stack_byte_swap_ladder(Type::I32, Value(0), Value(1));
        isel.select_block(entry, &instrs).unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        let rbits: Vec<_> = insts
            .iter()
            .filter(|inst| inst.opcode == AArch64Opcode::Rbit)
            .collect();
        assert_eq!(rbits.len(), 1, "expected one RBIT, got {insts:?}");
        assert!(
            !insts.iter().any(|inst| matches!(
                inst.opcode,
                AArch64Opcode::LdrRI
                    | AArch64Opcode::StrRI
                    | AArch64Opcode::LsrRI
                    | AArch64Opcode::LslRI
                    | AArch64Opcode::AndRI
                    | AArch64Opcode::OrrRR
            )),
            "stack-local bitreverse ladder should be skipped after RBIT selection: {insts:?}"
        );
        match rbits[0].operands[0] {
            ISelOperand::VReg(vreg) => assert_eq!(vreg.class, RegClass::Gpr32),
            ref other => panic!("expected Gpr32 RBIT destination, got {other:?}"),
        }
    }

