    #[test]
    fn select_fcvt_from_uint_i16_to_f16_uses_fpr16() {
        let (mut isel, entry) = make_empty_isel();
        let src = Value(0);
        let result = Value(1);
        let src_vreg = isel.new_vreg(RegClass::Gpr32);
        isel.define_value(src, ISelOperand::VReg(src_vreg), Type::I16);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::FcvtFromUint { src_ty: Type::I16 },
                args: vec![src],
                results: vec![result],
            },
            entry,
        )
        .unwrap();

        match isel.value_map.get(&result) {
            Some(ISelOperand::VReg(vreg)) => assert_eq!(vreg.class, RegClass::Fpr16),
            other => panic!("expected VReg result for fcvt u16->f16, got {:?}", other),
        }
        assert_eq!(isel.value_types.get(&result), Some(&Type::F16));

        let mfunc = isel.finalize();
        // Audit P0/G4: a narrow unsigned source (I16) is zero-extended (UXTH)
        // before UCVTF, since UCVTF reads the full source register and the u16's
        // upper sub-register bits are not guaranteed clean.
        assert_eq!(mfunc.blocks[&entry].insts[0].opcode, AArch64Opcode::Uxth);
        assert_eq!(mfunc.blocks[&entry].insts[1].opcode, AArch64Opcode::UcvtfRR);
    }

    #[test]
    fn select_fcvt_to_uint_f16_to_u16_uses_half_source_hint() {
        let (mut isel, entry) = make_empty_isel();
        let src = Value(0);
        let result = Value(1);
        let src_vreg = isel.new_vreg(RegClass::Fpr16);
        isel.define_value(src, ISelOperand::VReg(src_vreg), Type::F16);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::FcvtToUint { dst_ty: Type::I16 },
                args: vec![src],
                results: vec![result],
            },
            entry,
        )
        .unwrap();

        match isel.value_map.get(&result) {
            Some(ISelOperand::VReg(vreg)) => assert_eq!(vreg.class, RegClass::Gpr32),
            other => panic!(
                "expected Gpr32 VReg result for fcvt f16->u16, got {:?}",
                other
            ),
        }
        assert_eq!(isel.value_types.get(&result), Some(&Type::I16));

        let mfunc = isel.finalize();
        let inst = &mfunc.blocks[&entry].insts[0];
        assert_eq!(inst.opcode, AArch64Opcode::FcvtzuRR);
        assert_eq!(inst.operands[2], ISelOperand::Imm(16));
    }

