    #[test]
    fn select_array_gep_non_power_of_two_size() {
        // struct { I8, I8, I8 } has bytes()==3 (not power of two)
        //   → Movz + MulRR + AddRR
        let (mut isel, entry) = make_empty_isel();
        let base = isel.new_vreg(RegClass::Gpr64);
        let index = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(0), ISelOperand::VReg(base), Type::I64);
        isel.define_value(Value(1), ISelOperand::VReg(index), Type::I64);

        let elem_ty = Type::Struct(vec![Type::I8, Type::I8, Type::I8]);
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::ArrayGep { elem_ty },
                args: vec![Value(0), Value(1)],
                results: vec![Value(2)],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];
        assert_eq!(mblock.insts.len(), 3, "non-pow2 → Movz + MulRR + AddRR");
        assert_eq!(mblock.insts[0].opcode, AArch64Opcode::Movz);
        assert_eq!(mblock.insts[0].operands[1], ISelOperand::Imm(3));
        assert_eq!(mblock.insts[1].opcode, AArch64Opcode::MulRR);
        assert_eq!(mblock.insts[2].opcode, AArch64Opcode::AddRR);
    }

    #[test]
    fn select_array_gep_large_non_power_of_two_size_uses_movz_movk_chain() {
        // Element type of 70001 bytes (= [i8; 70001]) is non-power-of-two AND
        // wider than 0xFFFF, so the stride constant cannot be a bare MOVZ; it
        // must be materialized via the MOVZ/MOVK chain. Regression for the
        // #366-class bare-MOVZ crash.
        let (mut isel, entry) = make_empty_isel();
        let base = isel.new_vreg(RegClass::Gpr64);
        let index = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(0), ISelOperand::VReg(base), Type::I64);
        isel.define_value(Value(1), ISelOperand::VReg(index), Type::I64);

        let elem_ty = Type::Array(Box::new(Type::I8), 70001);
        assert!(!elem_ty.bytes().is_power_of_two() && elem_ty.bytes() > 0xFFFF);
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::ArrayGep { elem_ty },
                args: vec![Value(0), Value(1)],
                results: vec![Value(2)],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];
        // Every MOVZ/MOVK immediate must fit the 16-bit field.
        for inst in &mblock.insts {
            if matches!(inst.opcode, AArch64Opcode::Movz | AArch64Opcode::Movk)
                && let ISelOperand::Imm(v) = inst.operands[1]
            {
                assert!(
                    (0..=0xFFFF).contains(&v),
                    "MOVZ/MOVK immediate {v:#x} does not fit 16 bits"
                );
            }
        }
        // 70001 = 0x11171 -> MOVZ #0x1171 + MOVK #0x1, lsl 16.
        assert!(
            mblock.insts.iter().any(|i| i.opcode == AArch64Opcode::Movz),
            "stride must be materialized via a MOVZ"
        );
        assert!(
            mblock.insts.iter().any(|i| i.opcode == AArch64Opcode::Movk),
            "70001 needs a MOVK high chunk"
        );
        assert!(
            mblock
                .insts
                .iter()
                .any(|i| i.opcode == AArch64Opcode::MulRR),
            "stride is applied via MulRR"
        );
    }

    #[test]
    fn select_array_gep_result_type_is_pointer() {
        // The result of ArrayGep is always I64 (pointer), regardless of elem_ty.
        let (mut isel, entry) = make_empty_isel();
        let base = isel.new_vreg(RegClass::Gpr64);
        let index = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(0), ISelOperand::VReg(base), Type::I64);
        isel.define_value(Value(1), ISelOperand::VReg(index), Type::I64);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::ArrayGep { elem_ty: Type::F64 },
                args: vec![Value(0), Value(1)],
                results: vec![Value(2)],
            },
            entry,
        )
        .unwrap();

        // The value map should record Value(2) as I64.
        assert_eq!(isel.value_type(&Value(2)), Type::I64);
    }

    #[test]
    fn select_small_struct_return() {
        // Return a small struct (8 bytes, two i32 fields) packed in X0.
        // The return value is a pointer to the struct; select_return should
        // load it into X0.
        let struct_ty = Type::Struct(vec![Type::I32, Type::I32]);
        let sig = Signature {
            params: vec![],
            returns: vec![struct_ty.clone()],
        };
        let mut isel = InstructionSelector::new("ret_small".to_string(), sig);
        let entry = Block(0);
        isel.func.ensure_block(entry);

        // Define a pointer to the struct as a vreg
        let vreg = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(0), ISelOperand::VReg(vreg), struct_ty);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Return,
                args: vec![Value(0)],
                results: vec![],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];

        // ABI classifies 8-byte Struct return as Reg(X0). The isel layer
        // detects aggregate types and uses select_aggregate_return which
        // loads the struct from memory: single LDR X0, [src].
        let insts = &mblock.insts;
        // Find the LDR X0 instruction
        let ldr_inst = insts.iter().find(|i| {
            i.opcode == AArch64Opcode::LdrRI
                && i.operands.first() == Some(&ISelOperand::PReg(gpr::X0))
        });
        assert!(
            ldr_inst.is_some(),
            "Expected LDR X0 for small struct return"
        );
        // Must end with RET
        assert_eq!(insts.last().unwrap().opcode, AArch64Opcode::Ret);
    }

    #[test]
    fn select_medium_struct_return_16bytes() {
        // Return a 16-byte struct -> X0 + X1
        let struct_ty = Type::Struct(vec![Type::I64, Type::I64]);
        assert_eq!(struct_ty.bytes(), 16);

        let sig = Signature {
            params: vec![],
            returns: vec![struct_ty.clone()],
        };
        let mut isel = InstructionSelector::new("ret_med".to_string(), sig);
        let entry = Block(0);
        isel.func.ensure_block(entry);

        let vreg = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(0), ISelOperand::VReg(vreg), struct_ty);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Return,
                args: vec![Value(0)],
                results: vec![],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];
        let insts = &mblock.insts;

        // Should have LDR X0 at offset 0, LDR X1 at offset 8, then RET
        let ldr_x0 = insts.iter().find(|i| {
            i.opcode == AArch64Opcode::LdrRI
                && i.operands.first() == Some(&ISelOperand::PReg(gpr::X0))
        });
        assert!(ldr_x0.is_some(), "Expected LDR X0 for medium struct return");

        let ldr_x1 = insts.iter().find(|i| {
            i.opcode == AArch64Opcode::LdrRI
                && i.operands.first() == Some(&ISelOperand::PReg(gpr::X1))
        });
        assert!(ldr_x1.is_some(), "Expected LDR X1 for medium struct return");
        let ret = insts.last().unwrap();
        assert_eq!(ret.opcode, AArch64Opcode::Ret);
        assert!(
            ret.implicit_uses.contains(&gpr::X0),
            "RET must keep the low half of a medium aggregate return live"
        );
        assert!(
            ret.implicit_uses.contains(&gpr::X1),
            "RET must keep the high half of a medium aggregate return live"
        );
    }

    #[test]
    fn select_medium_struct_return_9bytes_keeps_x0_x1_live() {
        let struct_ty = Type::Array(Box::new(Type::I8), 9);
        assert_eq!(struct_ty.bytes(), 9);

        let sig = Signature {
            params: vec![],
            returns: vec![struct_ty.clone()],
        };
        let mut isel = InstructionSelector::new("ret_med_9".to_string(), sig);
        let entry = Block(0);
        isel.func.ensure_block(entry);

        let vreg = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(0), ISelOperand::VReg(vreg), struct_ty);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Return,
                args: vec![Value(0)],
                results: vec![],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];
        let insts = &mblock.insts;
        assert!(
            insts.iter().any(|i| {
                i.opcode == AArch64Opcode::LdrRI
                    && i.operands.first() == Some(&ISelOperand::PReg(gpr::X0))
                    && i.operands.get(2) == Some(&ISelOperand::Imm(0))
            }),
            "9-byte aggregate return must load the low 8 bytes into X0"
        );
        assert!(
            insts.iter().any(|i| {
                i.opcode == AArch64Opcode::LdrbRI
                    && i.operands.first() == Some(&ISelOperand::PReg(gpr::X1))
                    && i.operands.get(2) == Some(&ISelOperand::Imm(8))
            }),
            "9-byte aggregate return must load the high 1-byte tail into X1 without over-reading"
        );
        let ret = mblock.insts.last().unwrap();
        assert_eq!(ret.opcode, AArch64Opcode::Ret);
        assert!(
            ret.implicit_uses.contains(&gpr::X0),
            "RET must keep the low half of a 9-byte aggregate return live"
        );
        assert!(
            ret.implicit_uses.contains(&gpr::X1),
            "RET must keep the high half of a 9-byte aggregate return live"
        );
    }

    #[test]
    fn select_large_struct_return_via_sret() {
        // Return a large struct (24 bytes) -> store to [X8]
        let struct_ty = Type::Struct(vec![Type::I64, Type::I64, Type::I64]);
        assert_eq!(struct_ty.bytes(), 24);

        let sig = Signature {
            params: vec![],
            returns: vec![struct_ty.clone()],
        };
        let mut isel = InstructionSelector::new("ret_large".to_string(), sig);
        let entry = Block(0);
        isel.func.ensure_block(entry);

        let vreg = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(0), ISelOperand::VReg(vreg), struct_ty);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Return,
                args: vec![Value(0)],
                results: vec![],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];
        let insts = &mblock.insts;

        // Should have 3 LDR+STR pairs (24 bytes / 8 = 3 chunks) then RET
        let str_to_x8: Vec<_> = insts
            .iter()
            .filter(|i| {
                i.opcode == AArch64Opcode::StrRI
                    && i.operands.get(1) == Some(&ISelOperand::PReg(gpr::X8))
            })
            .collect();
        assert_eq!(
            str_to_x8.len(),
            3,
            "Expected 3 stores to X8 for 24-byte struct"
        );
        let ret = insts.last().unwrap();
        assert_eq!(ret.opcode, AArch64Opcode::Ret);
        assert!(
            !ret.implicit_uses.contains(&gpr::X8),
            "large sret returns write through X8 but do not return X8"
        );
    }

    #[test]
    fn select_hfa_f16_return_loads_h0_h1() {
        let struct_ty = Type::Struct(vec![Type::F16, Type::F16]);
        let sig = Signature {
            params: vec![],
            returns: vec![struct_ty.clone()],
        };
        let mut isel = InstructionSelector::new("ret_hfa_f16".to_string(), sig);
        let entry = Block(0);
        isel.func.ensure_block(entry);

        let vreg = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(0), ISelOperand::VReg(vreg), struct_ty);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Return,
                args: vec![Value(0)],
                results: vec![],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];
        let insts = &mblock.insts;

        let ldr_h0 = insts.iter().find(|i| {
            i.opcode == AArch64Opcode::LdrRI
                && i.operands.first() == Some(&ISelOperand::PReg(gpr::H0))
                && i.operands.get(2) == Some(&ISelOperand::Imm(0))
        });
        assert!(ldr_h0.is_some(), "Expected LDR H0 for first F16 HFA field");

        let ldr_h1 = insts.iter().find(|i| {
            i.opcode == AArch64Opcode::LdrRI
                && i.operands.first() == Some(&ISelOperand::PReg(gpr::H1))
                && i.operands.get(2) == Some(&ISelOperand::Imm(2))
        });
        assert!(ldr_h1.is_some(), "Expected LDR H1 for second F16 HFA field");
        assert_eq!(insts.last().unwrap().opcode, AArch64Opcode::Ret);
    }

