    #[test]
    fn select_call_with_small_aggregate_arg() {
        // Call a function that takes a small struct (8 bytes).
        // The ABI should pass it in a single register.
        let (mut isel, entry) = make_empty_isel();

        let struct_ty = Type::Struct(vec![Type::I32, Type::I32]);
        // Define a pointer to the struct
        let vreg = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(0), ISelOperand::VReg(vreg), struct_ty);

        // Define a result value
        let result_types = vec![Type::I32];
        isel.select_call("callee", &[Value(0)], &[Value(1)], &result_types, entry)
            .unwrap();

        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];

        // Should have: LDR X0 (aggregate arg), BL, MOV (result)
        let has_bl = mblock.insts.iter().any(|i| i.opcode == AArch64Opcode::Bl);
        assert!(has_bl, "Expected BL instruction for call");

        // The aggregate arg should be loaded into X0 (small struct -> Reg(X0))
        let ldr_x0 = mblock.insts.iter().find(|i| {
            i.opcode == AArch64Opcode::LdrRI
                && i.operands.first() == Some(&ISelOperand::PReg(gpr::X0))
        });
        assert!(ldr_x0.is_some(), "Expected LDR X0 for small aggregate arg");
    }

    #[test]
    fn select_call_with_large_aggregate_arg() {
        // Call a function that takes a large struct (24 bytes).
        // The ABI should pass it indirectly via pointer.
        let (mut isel, entry) = make_empty_isel();

        let struct_ty = Type::Struct(vec![Type::I64, Type::I64, Type::I64]);
        let vreg = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(0), ISelOperand::VReg(vreg), struct_ty);

        let result_types = vec![Type::I32];
        isel.select_call("callee_big", &[Value(0)], &[Value(1)], &result_types, entry)
            .unwrap();

        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];

        // Large aggregate -> Indirect{X0}, so should emit MovR to X0
        let mov_x0 = mblock.insts.iter().find(|i| {
            i.opcode == AArch64Opcode::MovR
                && i.operands.first() == Some(&ISelOperand::PReg(gpr::X0))
        });
        assert!(
            mov_x0.is_some(),
            "Expected MOV X0 for large aggregate indirect pass"
        );
    }

    #[test]
    fn select_call_returns_aggregate_via_sret() {
        // Call a function that returns a >16-byte aggregate (via X8 sret).
        // Audit P0/G1: the CALLER must allocate the result buffer and stage its
        // address into X8 BEFORE the call (X8 is call-clobbered and never
        // returned), then read the result from that buffer — NOT from X8 after
        // the call.
        let (mut isel, entry) = make_empty_isel();

        let struct_ty = Type::Struct(vec![Type::I64, Type::I64, Type::I64]);

        let result_types = vec![struct_ty];
        isel.select_call("returns_struct", &[], &[Value(0)], &result_types, entry)
            .unwrap();

        // The result value is defined (as the caller buffer address).
        assert!(
            isel.value_map.contains_key(&Value(0)),
            "sret aggregate result must be defined"
        );

        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];

        let bl = mblock
            .insts
            .iter()
            .position(|i| i.opcode == AArch64Opcode::Bl)
            .expect("expected a BL");

        // BEFORE the BL: a MovR that STAGES the buffer address INTO X8 (X8 is
        // the destination operand 0), and an AddPCRel that materializes the
        // caller-allocated buffer address.
        let mov_to_x8 = mblock.insts[..bl].iter().any(|i| {
            i.opcode == AArch64Opcode::MovR
                && i.operands.first() == Some(&ISelOperand::PReg(gpr::X8))
        });
        assert!(
            mov_to_x8,
            "expected a MOV that stages the sret buffer address into X8 before the call"
        );
        assert!(
            mblock.insts[..bl]
                .iter()
                .any(|i| i.opcode == AArch64Opcode::AddPCRel),
            "expected an AddPCRel allocating the caller sret result buffer"
        );

        // X8 must be a BL implicit-use so it stays live across the call.
        assert!(
            mblock.insts[bl].implicit_uses.contains(&gpr::X8),
            "expected X8 in the BL implicit-uses"
        );

        // The result must NOT be materialized by reading the clobbered X8 back
        // AFTER the call.
        let reads_x8_after = mblock.insts[bl + 1..].iter().any(|i| {
            i.opcode == AArch64Opcode::MovR
                && i.operands.get(1) == Some(&ISelOperand::PReg(gpr::X8))
        });
        assert!(
            !reads_x8_after,
            "sret result must come from the caller buffer, not a post-call read of X8"
        );
    }

    #[test]
    fn select_call_returns_small_aggregate_materializes_register_to_slot() {
        let (mut isel, entry) = make_empty_isel();
        let struct_ty = Type::Struct(vec![Type::I32, Type::I32]);

        isel.select_call(
            "returns_small_struct",
            &[],
            &[Value(0)],
            &[struct_ty],
            entry,
        )
        .unwrap();

        match isel.value_map.get(&Value(0)) {
            Some(ISelOperand::VReg(vreg)) => assert_eq!(vreg.class, RegClass::Gpr64),
            other => {
                panic!("expected aggregate call result to be stack-address vreg, got {other:?}")
            }
        }

        let mfunc = isel.finalize();
        assert_eq!(mfunc.stack_slots.len(), 1);
        assert_eq!(mfunc.stack_slots[0].size, 8);
        assert_eq!(mfunc.stack_slots[0].align, 8);

        let insts = &mfunc.blocks[&entry].insts;
        assert_eq!(insts[0].opcode, AArch64Opcode::Bl);
        assert_eq!(insts[1].opcode, AArch64Opcode::AddPCRel);
        assert_eq!(insts[1].operands[1], ISelOperand::PReg(SP));
        assert_eq!(insts[1].operands[2], ISelOperand::StackSlot(0));
        assert_eq!(insts[2].opcode, AArch64Opcode::StrRI);
        assert_eq!(insts[2].operands[0], ISelOperand::PReg(gpr::X0));
        assert_eq!(insts[2].operands[2], ISelOperand::Imm(0));
    }

