    /// The DivZero mirror of `select_guard_null_records_obligation_by_kernel_fingerprint`: a bound
    /// `GuardDivZero` records its obligation in `guard_obligations` keyed by the SAME single-operand
    /// `[divisor]` fingerprint the Certified-Elimination Kernel re-derives from the emitted
    /// `TrapDivZeroIfZero` carrier (`AArch64GuardTarget::operand_identity`).
    #[test]
    fn select_guard_div_zero_records_obligation_by_kernel_fingerprint() {
        use trust_cg_ir::guard::{GuardKind, GuardOperandRef, fingerprint_for_kind};

        let (mut isel, entry) = make_i64_isel();
        let obligation: u64 = 0x8000_0000;
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::GuardDivZero {
                    obligation: Some(obligation),
                },
                args: vec![Value(1)],
                results: vec![],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        // The carrier operand is VReg(1); the kernel lifts it to GuardOperandRef::Reg(1) and folds
        // in GuardKind::DivZero (defense-in-depth) to form the binding key.
        let fp = fingerprint_for_kind(GuardKind::DivZero, &[GuardOperandRef::Reg(1)]);
        assert_eq!(
            mfunc.guard_obligations.get(&fp),
            Some(&obligation),
            "the div-zero carrier must record its obligation keyed by the kernel's kind-folded [divisor] key"
        );
    }

