    /// The NotNull mirror of `select_guard_bounds_check_records_obligation_by_kernel_fingerprint`:
    /// a bound `GuardNull` records its obligation in `guard_obligations` keyed by the SAME
    /// single-operand `[ptr]` fingerprint the Certified-Elimination Kernel re-derives from the emitted
    /// `TrapNullIfZero` carrier (`AArch64GuardTarget::operand_identity`). This is the seam that makes a
    /// NotNull carrier kernel-authorizable end-to-end.
    #[test]
    fn select_guard_null_records_obligation_by_kernel_fingerprint() {
        use trust_cg_ir::guard::{GuardKind, GuardOperandRef, fingerprint_for_kind};

        let (mut isel, entry) = make_i64_isel();
        let obligation: u64 = 0x8000_0000;
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::GuardNull {
                    obligation: Some(obligation),
                },
                args: vec![Value(1)],
                results: vec![],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        // The carrier operand is VReg(1); the kernel lifts it to GuardOperandRef::Reg(1) and folds
        // in GuardKind::NullPtr (defense-in-depth) to form the binding key.
        let fp = fingerprint_for_kind(GuardKind::NullPtr, &[GuardOperandRef::Reg(1)]);
        assert_eq!(
            mfunc.guard_obligations.get(&fp),
            Some(&obligation),
            "the null carrier must record its obligation keyed by the kernel's kind-folded [ptr] key"
        );

        // SOUNDNESS (defense-in-depth, Item B): the SAME single operand under a DIFFERENT kind
        // (DivZero) keys a DISTINCT binding, so a NullPtr obligation can never be picked up by a
        // DivZero carrier over the same vreg (collision closed).
        let divzero_fp = fingerprint_for_kind(GuardKind::DivZero, &[GuardOperandRef::Reg(1)]);
        assert_ne!(fp, divzero_fp, "the kind must change the binding key");
        assert_eq!(mfunc.guard_obligations.get(&divzero_fp), None);
    }

