    /// The OVERFLOW mirror of `select_guard_shift_range_records_obligation_by_kernel_fingerprint`: a
    /// bound `GuardOverflow` records its obligation keyed by the SAME `[lhs, rhs, Imm(op_tag)]`
    /// fingerprint the kernel re-derives from the emitted carrier — INCLUDING the op-tag.
    #[test]
    fn select_guard_overflow_records_obligation_by_kernel_fingerprint() {
        use trust_cg_ir::guard::{GuardKind, GuardOperandRef, fingerprint_for_kind};
        use trust_cg_ir::{OverflowOp, pack_overflow_tag};

        let tag = pack_overflow_tag(OverflowOp::SignedAdd, 64);
        let (mut isel, entry) = make_i64_isel();
        let obligation: u64 = 0x9000_0000;
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::GuardOverflow {
                    op_tag: tag,
                    obligation: Some(obligation),
                },
                args: vec![Value(0), Value(1)],
                results: vec![],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        // A SignedAdd tag classifies to GuardKind::SignedOverflow (matches `overflow_carrier_kind`
        // on the kernel re-derive side).
        let fp = fingerprint_for_kind(
            GuardKind::SignedOverflow,
            &[
                GuardOperandRef::Reg(0),
                GuardOperandRef::Reg(1),
                GuardOperandRef::Imm(tag),
            ],
        );
        assert_eq!(
            mfunc.guard_obligations.get(&fp),
            Some(&obligation),
            "the overflow carrier must record its obligation keyed by the kernel's kind-folded \
             [lhs, rhs, Imm(op_tag)] key"
        );

        // SOUNDNESS: a DIFFERENT op-tag (unsigned add) keys a DIFFERENT binding (both the op-tag
        // operand AND the folded kind change), so the bound obligation does NOT discharge a wrong-op
        // carrier over the same registers.
        let wrong_tag = pack_overflow_tag(OverflowOp::UnsignedAdd, 64);
        let wrong_fp = fingerprint_for_kind(
            GuardKind::UnsignedOverflow,
            &[
                GuardOperandRef::Reg(0),
                GuardOperandRef::Reg(1),
                GuardOperandRef::Imm(wrong_tag),
            ],
        );
        assert_ne!(fp, wrong_fp, "op-tag/kind must change the binding key");
        assert_eq!(mfunc.guard_obligations.get(&wrong_fp), None);
    }

