    #[test]
    fn select_guard_bounds_check_records_obligation_by_kernel_fingerprint() {
        use trust_cg_ir::GuardTarget;
        let (mut isel, entry) = make_i64_isel();
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::GuardBoundsCheck {
                    bound: 8,
                    obligation: Some(42),
                },
                args: vec![Value(0), Value(1)],
                results: vec![],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        // The discharged obligation was recorded, keyed by a kind-folded binding key.
        assert_eq!(mfunc.guard_obligations.len(), 1);
        let (&recorded_fp, &oid) = mfunc.guard_obligations.iter().next().unwrap();
        assert_eq!(oid, 42);

        // SEAM: the recorded binding key MUST equal what the Certified-Elimination Kernel re-derives
        // from the emitted MachIR carrier — the carrier's GuardKind (via classify_carrier) folded
        // into its operand list (AArch64GuardTarget over [base, index, bound]). This is what lets the
        // codegen pipeline re-derive each carrier's obligation for the kernel gate.
        let ir = mfunc.to_ir_func();
        let carrier = ir
            .insts
            .iter()
            .find(|i| i.opcode == AArch64Opcode::TrapBoundsCheckExact)
            .expect("carrier present in MachIR");
        let kind = trust_cg_ir::AArch64GuardTarget
            .classify_carrier(carrier)
            .expect("carrier classifies");
        let identity = trust_cg_ir::AArch64GuardTarget.operand_identity(carrier);
        let kernel_fp = fingerprint_for_kind(kind, &identity.operands);
        assert_eq!(
            recorded_fp, kernel_fp,
            "ISel binding key must match kernel binding key"
        );
    }

    // =======================================================================
    // Coverage expansion: unconditional jump
    // =======================================================================

    #[test]
    fn select_jump_unconditional() {
        let (mut isel, entry) = make_empty_isel();
        let target = Block(1);
        isel.func.ensure_block(target);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Jump { dest: target },
                args: vec![],
                results: vec![],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];
        assert_eq!(mblock.insts.len(), 1);
        assert_eq!(mblock.insts[0].opcode, AArch64Opcode::B);
        assert_eq!(mblock.insts[0].operands[0], ISelOperand::Block(target));
        assert_eq!(mblock.successors.len(), 1);
        assert_eq!(mblock.successors[0], target);
    }

