    #[test]
    fn volatile_i128_load_and_store_fail_closed_instead_of_splitting() {
        let (mut load_isel, entry) = make_empty_isel();
        let addr = load_isel.new_vreg(RegClass::Gpr64);
        load_isel.define_value(Value(0), ISelOperand::VReg(addr), Type::I64);
        let load_err = load_isel
            .select_instruction(
                &Instruction {
                    opcode: Opcode::VolatileLoad {
                        ty: Type::I128,
                        align: Some(16),
                    },
                    args: vec![Value(0)],
                    results: vec![Value(1)],
                },
                entry,
            )
            .expect_err("volatile I128 load must not split into two reads");
        assert!(matches!(load_err, ISelError::UnsupportedOpcode(ref message)
                if message.contains("I128 load") && message.contains("two 64-bit accesses")));
        assert!(load_isel.func.blocks[&entry].insts.is_empty());

        let (mut store_isel, entry) = make_empty_isel();
        let addr = store_isel.new_vreg(RegClass::Gpr64);
        let lo = store_isel.new_vreg(RegClass::Gpr64);
        let hi = store_isel.new_vreg(RegClass::Gpr64);
        store_isel.define_value(Value(0), ISelOperand::VReg(addr), Type::I64);
        store_isel.define_i128_value(Value(1), lo, hi);
        let store_err = store_isel
            .select_instruction(
                &Instruction {
                    opcode: Opcode::VolatileStore {
                        ty: Type::I128,
                        align: Some(16),
                    },
                    args: vec![Value(1), Value(0)],
                    results: vec![],
                },
                entry,
            )
            .expect_err("volatile I128 store must not split into two writes");
        assert!(
            matches!(store_err, ISelError::UnsupportedOpcode(ref message)
                if message.contains("I128 store") && message.contains("two 64-bit accesses"))
        );
        assert!(store_isel.func.blocks[&entry].insts.is_empty());
    }

