    #[test]
    fn select_fconst_f16() {
        let (mut isel, entry) = make_empty_isel();
        let result = Value(0);
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Fconst {
                    ty: Type::F16,
                    imm: 1.0,
                },
                args: vec![],
                results: vec![result],
            },
            entry,
        )
        .unwrap();

        match isel.value_map.get(&result) {
            Some(ISelOperand::VReg(vreg)) => assert_eq!(vreg.class, RegClass::Fpr16),
            other => panic!("expected F16 fconst result vreg, got {:?}", other),
        }
        assert_eq!(isel.value_types.get(&result), Some(&Type::F16));

        let mfunc = isel.finalize();
        let inst = &mfunc.blocks[&entry].insts[0];
        assert_eq!(inst.opcode, AArch64Opcode::FmovImm);
        assert_eq!(inst.operands[1], ISelOperand::FImm(1.0));
    }

    #[test]
    fn select_fconst_f64() {
        let (mut isel, entry) = make_empty_isel();
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Fconst {
                    ty: Type::F64,
                    imm: 2.78,
                },
                args: vec![],
                results: vec![Value(0)],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        // 2.78 is NOT FMOV-immediate-encodable, so it is materialized as a GPR
        // bit pattern (MOVZ/MOVK) followed by FMOV GPR->FPR — not FmovImm (which
        // would silently encode +2.0).
        let insts = &mfunc.blocks[&entry].insts;
        assert_eq!(insts[0].opcode, AArch64Opcode::Movz);
        assert_eq!(insts.last().unwrap().opcode, AArch64Opcode::FmovGprFpr);
        assert!(insts.iter().all(|i| i.opcode != AArch64Opcode::FmovImm));
    }

