    #[test]
    fn select_fcmp_f16_equal_uses_fpr16() {
        let (mut isel, entry) = make_empty_isel();
        let lhs = Value(0);
        let rhs = Value(1);
        let result = Value(2);
        let lhs_vreg = isel.new_vreg(RegClass::Fpr16);
        let rhs_vreg = isel.new_vreg(RegClass::Fpr16);
        isel.define_value(lhs, ISelOperand::VReg(lhs_vreg), Type::F16);
        isel.define_value(rhs, ISelOperand::VReg(rhs_vreg), Type::F16);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Fcmp {
                    cond: FloatCC::Equal,
                },
                args: vec![lhs, rhs],
                results: vec![result],
            },
            entry,
        )
        .unwrap();

        match isel.value_map.get(&result) {
            Some(ISelOperand::VReg(vreg)) => assert_eq!(vreg.class, RegClass::Gpr64),
            other => panic!("expected Gpr64 VReg result for fcmp f16, got {:?}", other),
        }
        assert_eq!(isel.value_types.get(&result), Some(&Type::B1));

        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];
        assert_eq!(mblock.insts[0].opcode, AArch64Opcode::Fcmp);
        match &mblock.insts[0].operands[0] {
            ISelOperand::VReg(vreg) => assert_eq!(vreg.class, RegClass::Fpr16),
            other => panic!("expected Fpr16 lhs for fcmp f16, got {:?}", other),
        }
        match &mblock.insts[0].operands[1] {
            ISelOperand::VReg(vreg) => assert_eq!(vreg.class, RegClass::Fpr16),
            other => panic!("expected Fpr16 rhs for fcmp f16, got {:?}", other),
        }
        assert_eq!(mblock.insts[1].opcode, AArch64Opcode::CSet);
        assert_eq!(
            mblock.insts[1].operands[1],
            ISelOperand::CondCode(AArch64CC::EQ)
        );
    }

