        // Release Add emits LDADDL (A=0, R=1) — not a codegen error, and not the
        // over-strengthened acqrel LDADDAL.
        let (mut isel, entry) = make_empty_isel();
        let val_vreg = isel.new_vreg(RegClass::Gpr64);
