    #[test]
    fn select_cmpxchg_release_relaxed_emits_casl() {
        // Was `..._emits_casal`: a release-only CAS used to take the
        // strictly-stronger CASAL because CASL was not encoded. The dedicated
        // store-release-only CASL (A=0, o0/R=1) is now selected — the EXACT
        // requested ordering. The rwlock `read_unlock` fast path needs this
        // shape.
        let (mut isel, entry) = make_empty_isel();
        let exp_vreg = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(0), ISelOperand::VReg(exp_vreg), Type::I64);
        let des_vreg = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(1), ISelOperand::VReg(des_vreg), Type::I64);
        let addr_vreg = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(2), ISelOperand::VReg(addr_vreg), Type::I64);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::CmpXchg {
                    ty: Type::I64,
                    success: AtomicOrdering::Release,
                    failure: AtomicOrdering::Relaxed,
                },
                args: vec![Value(0), Value(1), Value(2)],
                results: vec![Value(3)],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        assert_eq!(
            mfunc.blocks[&entry].insts[1].opcode,
            AArch64Opcode::Casl,
            "release-only CmpXchg must emit the exact release-only CASL"
        );
        assert_ne!(
            mfunc.blocks[&entry].insts[1].opcode,
            AArch64Opcode::Casal,
            "release-only CmpXchg must NOT emit the AcqRel CASAL (over-strengthened ordering)"
        );
    }

    /// Pin the aligned cmpxchg failure-ordering rule (one rule — adapter,
    /// AArch64 ISel, x86-64 ISel): a failure ordering STRONGER than the
    /// success ordering is LEGAL (Rust/LLVM); the ISel lifts the success side
    /// and picks the covering CAS variant.
    #[test]
    fn select_cmpxchg_stronger_failure_lifts_and_selects_covering_cas() {
        for (success, failure, want) in [
            // failure Acquire over Relaxed success: lift to Acquire → CASA.
            (
                AtomicOrdering::Relaxed,
                AtomicOrdering::Acquire,
                AArch64Opcode::Casa,
            ),
            // failure Acquire over Release success: lift to AcqRel → CASAL.
            (
                AtomicOrdering::Release,
                AtomicOrdering::Acquire,
                AArch64Opcode::Casal,
            ),
            // failure SeqCst over anything: lift to SeqCst → CASAL.
            (
                AtomicOrdering::Relaxed,
                AtomicOrdering::SeqCst,
                AArch64Opcode::Casal,
            ),
            (
                AtomicOrdering::Acquire,
                AtomicOrdering::SeqCst,
                AArch64Opcode::Casal,
            ),
        ] {
            let (mut isel, entry) = make_empty_isel();
            let exp_vreg = isel.new_vreg(RegClass::Gpr64);
            isel.define_value(Value(0), ISelOperand::VReg(exp_vreg), Type::I64);
            let des_vreg = isel.new_vreg(RegClass::Gpr64);
            isel.define_value(Value(1), ISelOperand::VReg(des_vreg), Type::I64);
            let addr_vreg = isel.new_vreg(RegClass::Gpr64);
            isel.define_value(Value(2), ISelOperand::VReg(addr_vreg), Type::I64);

            isel.select_instruction(
                &Instruction {
                    opcode: Opcode::CmpXchg {
                        ty: Type::I64,
                        success,
                        failure,
                    },
                    args: vec![Value(0), Value(1), Value(2)],
                    results: vec![Value(3)],
                },
                entry,
            )
            .unwrap_or_else(|e| {
                panic!("cmpxchg ({success:?}, {failure:?}) must be accepted: {e:?}")
            });

            let mfunc = isel.finalize();
            assert_eq!(
                mfunc.blocks[&entry].insts[1].opcode, want,
                "({success:?}, {failure:?}) must lift to the covering {want:?}"
            );
        }
    }

    /// The only invalid cmpxchg failure orderings are Release/AcqRel — a
    /// failed exchange performs no store (Rust/LLVM rule, aligned across the
    /// adapter and both ISels).
    #[test]
    fn select_cmpxchg_release_acqrel_failure_fails_closed() {
        for failure in [AtomicOrdering::Release, AtomicOrdering::AcqRel] {
            let (mut isel, entry) = make_empty_isel();
            let exp_vreg = isel.new_vreg(RegClass::Gpr64);
            isel.define_value(Value(0), ISelOperand::VReg(exp_vreg), Type::I64);
            let des_vreg = isel.new_vreg(RegClass::Gpr64);
            isel.define_value(Value(1), ISelOperand::VReg(des_vreg), Type::I64);
            let addr_vreg = isel.new_vreg(RegClass::Gpr64);
            isel.define_value(Value(2), ISelOperand::VReg(addr_vreg), Type::I64);

            let result = isel.select_instruction(
                &Instruction {
                    opcode: Opcode::CmpXchg {
                        ty: Type::I64,
                        success: AtomicOrdering::SeqCst,
                        failure,
                    },
                    args: vec![Value(0), Value(1), Value(2)],
                    results: vec![Value(3)],
                },
                entry,
            );
            assert!(
                matches!(
                    result,
                    Err(ISelError::UnsupportedCmpXchg {
                        reason: "invalid compare-exchange failure ordering",
                        ..
                    })
                ),
                "failure ordering {failure:?} must fail closed"
            );
        }
    }

