    #[test]
    fn select_memmove_passes_address_carried_aggregate_as_pointer() {
        let (mut isel, entry) = make_empty_isel();

        let dest = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(0), ISelOperand::VReg(dest), Type::I64);
        let source_addr = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(
            Value(1),
            ISelOperand::VReg(source_addr),
            Type::Struct(vec![Type::I64, Type::I64]),
        );
        let len = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(2), ISelOperand::VReg(len), Type::I64);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Memmove,
                args: vec![Value(0), Value(1), Value(2)],
                results: vec![],
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let insts = &mfunc.blocks[&entry].insts;
        assert!(
            insts.iter().any(|inst| {
                inst.opcode == AArch64Opcode::Copy
                    && inst.operands
                        == vec![ISelOperand::PReg(gpr::X1), ISelOperand::VReg(source_addr)]
            }),
            "aggregate source address must be passed directly in X1: {insts:?}"
        );
        assert!(
            insts
                .iter()
                .all(|inst| !matches!(inst.opcode, AArch64Opcode::LdrRI | AArch64Opcode::LdpRI)),
            "memmove must not expand an address-carried aggregate by value: {insts:?}"
        );
        let call = insts
            .iter()
            .find(|inst| inst.opcode == AArch64Opcode::Bl)
            .expect("memmove call");
        assert_eq!(call.implicit_uses, vec![gpr::X0, gpr::X1, gpr::X2]);
    }

