    #[test]
    fn select_memory_intrinsics_fail_closed_for_extra_operands_and_results() {
        let (mut isel, entry) = make_empty_isel();
        for idx in 0..4u32 {
            let vreg = isel.new_vreg(RegClass::Gpr64);
            isel.define_value(Value(idx), ISelOperand::VReg(vreg), Type::I64);
        }

        let extra = isel
            .select_instruction(
                &Instruction {
                    opcode: Opcode::Memcpy,
                    args: vec![Value(0), Value(1), Value(2), Value(3)],
                    results: vec![],
                },
                entry,
            )
            .unwrap_err();
        assert!(matches!(
            extra,
            ISelError::WrongArgCount {
                expected: 3,
                actual: 4,
                context: "Memcpy"
            }
        ));

        let result = isel
            .select_instruction(
                &Instruction {
                    opcode: Opcode::Memmove,
                    args: vec![Value(0), Value(1), Value(2)],
                    results: vec![Value(4)],
                },
                entry,
            )
            .unwrap_err();
        assert!(matches!(
            result,
            ISelError::UnexpectedResults {
                actual: 1,
                context: "Memmove"
            }
        ));
    }

    // =======================================================================
    // PIECE 1: small constant-length memcpy inlining (exact lanes, no libcall)
    // =======================================================================

    /// Select a `memcpy(dest, src, len)` with a compile-time-constant length and
    /// return the emitted `(opcode, operands)` sequence. `dest`/`src` are I64
    /// pointer vregs; `len` is seeded into `iconst_origins`.
    fn run_const_memcpy(len: i64) -> Vec<(AArch64Opcode, Vec<ISelOperand>)> {
        let (mut isel, entry) = make_empty_isel();
        let d = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(0), ISelOperand::VReg(d), Type::I64);
        let s = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(1), ISelOperand::VReg(s), Type::I64);
        isel.iconst_origins.insert(Value(2), (Type::I64, len));
        isel.value_types.insert(Value(2), Type::I64);
        isel.current_block = Some(entry);
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Memcpy,
                args: vec![Value(0), Value(1), Value(2)],
                results: vec![],
            },
            entry,
        )
        .unwrap();
        let mfunc = isel.finalize();
        mfunc.blocks[&entry]
            .insts
            .iter()
            .map(|i| (i.opcode, i.operands.clone()))
            .collect()
    }

    fn imm_last(operands: &[ISelOperand]) -> i64 {
        match operands.last() {
            Some(ISelOperand::Imm(v)) => *v,
            other => panic!("expected trailing Imm operand, got {other:?}"),
        }
    }

    /// Byte width of a load lane, or `None` for a non-load opcode. `LdrRI`'s
    /// width follows the destination register class (X=8, W=4).
    fn load_lane_width(opc: AArch64Opcode, operands: &[ISelOperand]) -> Option<u64> {
        match opc {
            AArch64Opcode::LdpRI => Some(16),
            AArch64Opcode::LdrRI => match operands.first() {
                Some(ISelOperand::VReg(v)) if v.class == RegClass::Gpr64 => Some(8),
                Some(ISelOperand::VReg(v)) if v.class == RegClass::Gpr32 => Some(4),
                _ => None,
            },
            AArch64Opcode::LdrhRI => Some(2),
            AArch64Opcode::LdrbRI => Some(1),
            _ => None,
        }
    }

    fn store_lane_width(opc: AArch64Opcode, operands: &[ISelOperand]) -> Option<u64> {
        match opc {
            AArch64Opcode::StpRI => Some(16),
            AArch64Opcode::StrRI => match operands.first() {
                Some(ISelOperand::VReg(v)) if v.class == RegClass::Gpr64 => Some(8),
                Some(ISelOperand::VReg(v)) if v.class == RegClass::Gpr32 => Some(4),
                _ => None,
            },
            AArch64Opcode::StrhRI => Some(2),
            AArch64Opcode::StrbRI => Some(1),
            _ => None,
        }
    }

    #[test]
    fn memcpy_const_len_0_emits_nothing() {
        let insts = run_const_memcpy(0);
        assert!(insts.is_empty(), "len 0 memcpy is a no-op, got {insts:?}");
    }

    #[test]
    fn memcpy_const_len_16_is_single_ldp_stp() {
        let insts = run_const_memcpy(16);
        let opcs: Vec<_> = insts.iter().map(|(o, _)| *o).collect();
        assert_eq!(
            opcs,
            vec![AArch64Opcode::LdpRI, AArch64Opcode::StpRI],
            "16-byte copy is exactly one LDP/STP pair"
        );
    }

    #[test]
    fn memcpy_const_len_32_is_two_ldp_stp_chunks() {
        let insts = run_const_memcpy(32);
        let opcs: Vec<_> = insts.iter().map(|(o, _)| *o).collect();
        assert_eq!(
            opcs,
            vec![
                AArch64Opcode::LdpRI,
                AArch64Opcode::StpRI,
                AArch64Opcode::LdpRI,
                AArch64Opcode::StpRI,
            ]
        );
        // Second chunk is at byte offset 16.
        assert_eq!(imm_last(&insts[2].1), 16);
        assert_eq!(imm_last(&insts[3].1), 16);
    }

    #[test]
    fn memcpy_const_len_13_lanes_8_4_1() {
        // 13 = 8 + 4 + 1 at offsets 0, 8, 12 — EXACT, no over-read.
        let insts = run_const_memcpy(13);
        let opcs: Vec<_> = insts.iter().map(|(o, _)| *o).collect();
        assert_eq!(
            opcs,
            vec![
                AArch64Opcode::LdrRI, // x @0
                AArch64Opcode::StrRI,
                AArch64Opcode::LdrRI, // w @8
                AArch64Opcode::StrRI,
                AArch64Opcode::LdrbRI, // b @12
                AArch64Opcode::StrbRI,
            ]
        );
        assert_eq!(load_lane_width(insts[0].0, &insts[0].1), Some(8));
        assert_eq!(load_lane_width(insts[2].0, &insts[2].1), Some(4));
        assert_eq!(imm_last(&insts[4].1), 12);
    }

    #[test]
    fn memcpy_const_len_31_lanes_16_8_4_2_1() {
        // 31 = 16 + 8 + 4 + 2 + 1 at offsets 0, 16, 24, 28, 30.
        let insts = run_const_memcpy(31);
        let opcs: Vec<_> = insts.iter().map(|(o, _)| *o).collect();
        assert_eq!(
            opcs,
            vec![
                AArch64Opcode::LdpRI, // 16 @0
                AArch64Opcode::StpRI,
                AArch64Opcode::LdrRI, // x @16
                AArch64Opcode::StrRI,
                AArch64Opcode::LdrRI, // w @24
                AArch64Opcode::StrRI,
                AArch64Opcode::LdrhRI, // h @28
                AArch64Opcode::StrhRI,
                AArch64Opcode::LdrbRI, // b @30
                AArch64Opcode::StrbRI,
            ]
        );
    }

    /// EXHAUSTIVE exact-lane coverage: for every inlined length 1..=32, the load
    /// lanes tile `[0, len)` with no gap, no overlap, and no byte read past
    /// `len` (the property that makes an end-of-allocation copy safe), the store
    /// lanes mirror them exactly, and no libc `Bl` is emitted.
    #[test]
    fn memcpy_const_lens_exact_lane_coverage() {
        for len in 1..=INLINE_MEMCPY_MAX_BYTES {
            let insts = run_const_memcpy(len);
            assert!(
                !insts.iter().any(|(o, _)| *o == AArch64Opcode::Bl),
                "len {len}: inlined copy must not call memcpy"
            );
            let n = len as usize;
            let mut loaded = vec![false; n];
            let mut stored = vec![false; n];
            for (opc, ops) in &insts {
                if let Some(w) = load_lane_width(*opc, ops) {
                    let off = imm_last(ops) as usize;
                    let end = off + w as usize;
                    assert!(end <= n, "len {len}: load reads byte {end} past end");
                    for (relative, was_loaded) in loaded[off..end].iter_mut().enumerate() {
                        let b = off + relative;
                        assert!(!*was_loaded, "len {len}: byte {b} loaded twice");
                        *was_loaded = true;
                    }
                } else if let Some(w) = store_lane_width(*opc, ops) {
                    let off = imm_last(ops) as usize;
                    let end = off + w as usize;
                    assert!(end <= n, "len {len}: store writes byte {end} past end");
                    for (relative, was_stored) in stored[off..end].iter_mut().enumerate() {
                        let b = off + relative;
                        assert!(!*was_stored, "len {len}: byte {b} stored twice");
                        *was_stored = true;
                    }
                }
            }
            assert!(
                loaded.iter().all(|&c| c),
                "len {len}: source not fully read"
            );
            assert!(
                stored.iter().all(|&c| c),
                "len {len}: dest not fully written"
            );
        }
    }

    #[test]
    fn memcpy_const_len_33_keeps_libcall() {
        // 33 > INLINE_MEMCPY_MAX_BYTES: the boundary just above the inline cap.
        let insts = run_const_memcpy(INLINE_MEMCPY_MAX_BYTES + 1);
        assert!(
            insts.iter().any(|(o, _)| *o == AArch64Opcode::Bl),
            "len 33 must fall back to the libc memcpy call"
        );
    }

