    // =======================================================================
    // PIECE 2: constant GEP/Iadd offset -> ADD-immediate addressing
    // =======================================================================

    #[test]
    fn add_imm12_form_boundaries() {
        use AArch64Opcode::{AddRI, AddRIShift12};
        assert_eq!(aarch64_add_imm12_form(0), Some((AddRI, 0)));
        assert_eq!(aarch64_add_imm12_form(1), Some((AddRI, 1)));
        assert_eq!(aarch64_add_imm12_form(0xFFF), Some((AddRI, 0xFFF)));
        // Just above imm12: only encodable as an LSL#12 form because low bits clear.
        assert_eq!(aarch64_add_imm12_form(0x1000), Some((AddRIShift12, 1)));
        assert_eq!(aarch64_add_imm12_form(0x2000), Some((AddRIShift12, 2)));
        assert_eq!(
            aarch64_add_imm12_form(0xFFF000),
            Some((AddRIShift12, 0xFFF))
        );
        // Both halves set -> needs two adds -> not a single-instruction form.
        assert_eq!(aarch64_add_imm12_form(0x1001), None);
        // Beyond 0xFFF<<12.
        assert_eq!(aarch64_add_imm12_form(0x1000000), None);
        // Negative displacement is not ADD-immediate encodable.
        assert_eq!(aarch64_add_imm12_form(-1), None);
        // A 0xFADE global-address stub magnitude (never a plain Iconst at ISel,
        // but the guard rejects it regardless of how it might arrive).
        assert_eq!(
            aarch64_add_imm12_form(0xFADE_0000_0000_0004_u64 as i64),
            None
        );
    }

    /// Select `Iadd(a0, a1)` where one operand is a seeded constant; return the
    /// emitted opcode sequence.
    fn run_iadd_with_const(
        const_on_rhs: bool,
        const_val: i64,
        ty: Type,
    ) -> Vec<(AArch64Opcode, Vec<ISelOperand>)> {
        let (mut isel, entry) = make_empty_isel();
        let reg = isel.new_vreg(reg_class_for_type(&ty));
        let (reg_v, const_v) = if const_on_rhs {
            (Value(0), Value(1))
        } else {
            (Value(1), Value(0))
        };
        isel.define_value(reg_v, ISelOperand::VReg(reg), ty.clone());
        isel.value_types.insert(reg_v, ty.clone());
        isel.iconst_origins.insert(const_v, (ty.clone(), const_val));
        isel.value_types.insert(const_v, ty.clone());
        isel.current_block = Some(entry);
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Iadd,
                args: vec![Value(0), Value(1)],
                results: vec![Value(2)],
            },
            entry,
        )
        .unwrap();
        let mfunc = isel.finalize();
        mfunc.blocks[&entry]
            .insts
            .iter()
            .map(|i| (i.opcode, i.operands.clone()))
            .collect()
    }

    #[test]
    fn iadd_const_rhs_folds_to_addri() {
        let insts = run_iadd_with_const(true, 20, Type::I64);
        assert_eq!(insts.len(), 1, "one folded ADD, no MOVZ: {insts:?}");
        assert_eq!(insts[0].0, AArch64Opcode::AddRI);
        assert_eq!(imm_last(&insts[0].1), 20);
    }

    #[test]
    fn iadd_const_lhs_folds_commutatively() {
        let insts = run_iadd_with_const(false, 12, Type::I64);
        assert_eq!(insts.len(), 1, "const on LHS still folds: {insts:?}");
        assert_eq!(insts[0].0, AArch64Opcode::AddRI);
        assert_eq!(imm_last(&insts[0].1), 12);
    }

    #[test]
    fn iadd_const_shift12_folds() {
        let insts = run_iadd_with_const(true, 0x2000, Type::I64);
        assert_eq!(insts.len(), 1);
        assert_eq!(insts[0].0, AArch64Opcode::AddRIShift12);
        assert_eq!(imm_last(&insts[0].1), 2);
    }

    #[test]
    fn iadd_i32_const_folds_to_addri() {
        let insts = run_iadd_with_const(true, 7, Type::I32);
        assert_eq!(insts.len(), 1);
        assert_eq!(insts[0].0, AArch64Opcode::AddRI);
        assert_eq!(imm_last(&insts[0].1), 7);
    }

    #[test]
    fn iadd_nonencodable_const_falls_back_to_register_add() {
        // 0x1001 is not a single ADD-immediate: keep the materialize + AddRR.
        let insts = run_iadd_with_const(true, 0x1001, Type::I64);
        assert!(
            insts.iter().any(|(o, _)| *o == AArch64Opcode::AddRR),
            "non-encodable constant must use the register add path: {insts:?}"
        );
        assert!(
            !insts
                .iter()
                .any(|(o, _)| matches!(o, AArch64Opcode::AddRI | AArch64Opcode::AddRIShift12)),
            "must not emit a truncated ADD-immediate: {insts:?}"
        );
    }

    #[test]
    fn iadd_small_negative_const_folds_to_subri() {
        // `x + (-3)` == `x - 3`: a small negative constant folds to a single
        // SUB (immediate), not a materialize + AddRR. This is the loop
        // decrement `i--` (`add i, -1`) that otherwise squats a register on the
        // constant. Fires for RHS or LHS constant (addition commutes).
        for on_rhs in [true, false] {
            let insts = run_iadd_with_const(on_rhs, -3, Type::I64);
            assert_eq!(insts.len(), 1, "one folded SUB, no MOVZ: {insts:?}");
            assert_eq!(insts[0].0, AArch64Opcode::SubRI);
            assert_eq!(imm_last(&insts[0].1), 3, "negated to +3");
        }
        // The canonical decrement `i - 1`.
        let dec = run_iadd_with_const(true, -1, Type::I64);
        assert_eq!(dec[0].0, AArch64Opcode::SubRI);
        assert_eq!(imm_last(&dec[0].1), 1);
        // 32-bit decrement folds too (SubRI on the W register).
        let dec32 = run_iadd_with_const(true, -1, Type::I32);
        assert_eq!(dec32[0].0, AArch64Opcode::SubRI);
        assert_eq!(imm_last(&dec32[0].1), 1);
    }

    #[test]
    fn iadd_min_negative_imm12_folds_to_subri() {
        // -0xFFF is the largest-magnitude single SUB-immediate.
        let insts = run_iadd_with_const(true, -0xFFF, Type::I64);
        assert_eq!(insts.len(), 1);
        assert_eq!(insts[0].0, AArch64Opcode::SubRI);
        assert_eq!(imm_last(&insts[0].1), 0xFFF);
    }

    #[test]
    fn iadd_large_negative_const_falls_back_to_register_add() {
        // -0x1001 exceeds the imm12 SUB range and there is no SubRIShift12, so
        // it keeps the materialize + AddRR path (no truncated/wrong immediate).
        let insts = run_iadd_with_const(true, -0x1001, Type::I64);
        assert!(
            insts.iter().any(|(o, _)| *o == AArch64Opcode::AddRR),
            "out-of-range negative constant must use the register add path: {insts:?}"
        );
        assert!(
            !insts.iter().any(|(o, _)| *o == AArch64Opcode::SubRI),
            "must not emit a truncated SUB-immediate: {insts:?}"
        );
    }

    /// Select an `ArrayGep(elem_ty)` with a seeded constant index; return the
    /// emitted opcode sequence. (The ArrayGep path is still reached for
    /// multi-index / ExtractElement GEPs.)
    fn run_array_gep_const_index(
        elem_ty: Type,
        index: i64,
    ) -> Vec<(AArch64Opcode, Vec<ISelOperand>)> {
        let (mut isel, entry) = make_empty_isel();
        let base = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(0), ISelOperand::VReg(base), Type::I64);
        isel.iconst_origins.insert(Value(1), (Type::I64, index));
        isel.value_types.insert(Value(1), Type::I64);
        isel.current_block = Some(entry);
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::ArrayGep { elem_ty },
                args: vec![Value(0), Value(1)],
                results: vec![Value(2)],
            },
            entry,
        )
        .unwrap();
        let mfunc = isel.finalize();
        mfunc.blocks[&entry]
            .insts
            .iter()
            .map(|i| (i.opcode, i.operands.clone()))
            .collect()
    }

    #[test]
    fn array_gep_const_index_elem1_folds_to_addri() {
        let insts = run_array_gep_const_index(Type::I8, 12);
        assert_eq!(insts.len(), 1);
        assert_eq!(insts[0].0, AArch64Opcode::AddRI);
        assert_eq!(imm_last(&insts[0].1), 12);
    }

    #[test]
    fn array_gep_const_index_scaled_folds_to_addri() {
        // i32 elements: index 5 -> byte offset 20.
        let insts = run_array_gep_const_index(Type::I32, 5);
        assert_eq!(insts.len(), 1);
        assert_eq!(insts[0].0, AArch64Opcode::AddRI);
        assert_eq!(imm_last(&insts[0].1), 20);
    }

    #[test]
    fn array_gep_const_index_zero_is_pointer_copy() {
        let insts = run_array_gep_const_index(Type::I32, 0);
        assert_eq!(insts.len(), 1);
        assert_eq!(insts[0].0, AArch64Opcode::MovR);
    }

    #[test]
    fn array_gep_const_index_nonencodable_falls_back() {
        // i32 elements, index 0x800 -> byte offset 0x2000 (encodable via LSL#12).
        let enc = run_array_gep_const_index(Type::I32, 0x800);
        assert_eq!(enc[0].0, AArch64Opcode::AddRIShift12);
        // i32 elements, index 0x401 -> 0x1004 -> both halves set -> NOT foldable;
        // drops to the shift-then-add path (LslRI + AddRR).
        let insts = run_array_gep_const_index(Type::I32, 0x401);
        assert!(
            insts.iter().any(|(o, _)| *o == AArch64Opcode::AddRR),
            "non-encodable scaled offset uses the register path: {insts:?}"
        );
        assert!(!insts.iter().any(|(o, _)| *o == AArch64Opcode::AddRI));
    }

    #[test]
    fn array_gep_runtime_index_unchanged() {
        // A non-constant index keeps the existing AddRR (elem 1) form.
        let (mut isel, entry) = make_empty_isel();
        let base = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(0), ISelOperand::VReg(base), Type::I64);
        let idx = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(1), ISelOperand::VReg(idx), Type::I64);
        isel.current_block = Some(entry);
        isel.select_instruction(
            &Instruction {
                opcode: Opcode::ArrayGep { elem_ty: Type::I8 },
                args: vec![Value(0), Value(1)],
                results: vec![Value(2)],
            },
            entry,
        )
        .unwrap();
        let mfunc = isel.finalize();
        assert_eq!(mfunc.blocks[&entry].insts[0].opcode, AArch64Opcode::AddRR);
    }

    #[test]
    fn select_memset_no_results() {
        // memset produces no results (void return)
        let (mut isel, entry) = make_empty_isel();

        let v0 = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(0), ISelOperand::VReg(v0), Type::I64);
        let v1 = isel.new_vreg(RegClass::Gpr32);
        isel.define_value(Value(1), ISelOperand::VReg(v1), Type::I32);
        let v2 = isel.new_vreg(RegClass::Gpr64);
        isel.define_value(Value(2), ISelOperand::VReg(v2), Type::I64);

        isel.select_instruction(
            &Instruction {
                opcode: Opcode::Memset,
                args: vec![Value(0), Value(1), Value(2)],
                results: vec![], // void
            },
            entry,
        )
        .unwrap();

        let mfunc = isel.finalize();
        let mblock = &mfunc.blocks[&entry];

        // After BL, there should be no result copy (no return value)
        let bl_idx = mblock
            .insts
            .iter()
            .position(|i| i.opcode == AArch64Opcode::Bl)
            .unwrap();
        // No Copy/MovR after the BL (no return value to copy)
        let post_bl_copy = mblock.insts[bl_idx + 1..]
            .iter()
            .any(|i| i.opcode == AArch64Opcode::MovR || i.opcode == AArch64Opcode::Copy);
        assert!(!post_bl_copy, "memset is void — no result copy after BL");
    }

